window.registerPaintingArtists&&window.registerPaintingArtists({"sano_di_pietro":{"name":"Сано ди Пьетро","latin":"Sano di Pietro","life":"1406–1481","tag":"Италия · кватроченто","aliases":["Сано ди Пьетро","Sano di Pietro"],"bio":["Кливленд указывает годы жизни Сано ди Пьетро — 1406–1481. В нашем собрании от него одна небольшая вещь.","Другие подробности его биографии в выбранной музейной записи не приводятся."],"technique":["Кливлендская доска изображает Мадонну с Младенцем, которых почитают святые Мария Магдалина и Николай Барийский, а над сценой помещено Распятие с Марией и Иоанном.","Музей отмечает деталь, которую легко пропустить: боковые стороны и оборот доски художник покрыл тонким слоем левкаса (штукатурки), сохранив текстуру грубого дерева, и расписал под порфир — ценный камень."],"innovation":"Музей подчёркивает не новизну композиции, а отношение к вещи: доска — это предмет, у которого отделан даже оборот. Роспись под порфир превращала деревянную конструкцию в драгоценный объект.","features":["Золотой фон: доска на дереве с золотом.","Два яруса: Мадонна со святыми и Распятие над ними.","Святые рядом с Богоматерью: Мария Магдалина и Николай Барийский.","Имитация камня: порфир на боковых сторонах и обороте.","Видимая фактура дерева: левкас положен тонким слоем."],"caution":"Музейная запись коротка: описание касается только отделки доски, а не общего стиля мастера. Не делай по этой записи выводов о всей его манере.","sources":[["Cleveland Museum of Art: Virgin and Child Adored by Saints Mary Magdalene and Nicolas of Bari","https://clevelandart.org/art/1924.199"]],"works":[{"key":"cma:106094","date":"1400s","image":"https://openaccess-cdn.clevelandart.org/1924.199/1924.199_web.jpg","zoom":"https://openaccess-cdn.clevelandart.org/1924.199/1924.199_print.jpg","source":"https://clevelandart.org/art/1924.199","museum":"Cleveland Museum of Art","originalTitle":"Virgin and Child Adored by Saints Mary Magdalene and Nicolas of Bari;  Christ Crucified with the Virgin and Saint John the Evangelist","medium":"tempera and gold on wood","title":"Мадонна со святыми; Распятие","look":"Над Мадонной со святыми Магдалиной и Николаем находится Распятие с Марией и Иоанном. Музей обращает внимание на левкас на боковых сторонах и обороте, расписанный под порфир."}]},"battista_di_biagio_sanguigni":{"name":"Баттиста ди Бьяджо Сангвиньи","latin":"Battista di Biagio Sanguigni","life":"работал 1393–1451","tag":"Италия · кватроченто","aliases":["Баттиста ди Бьяджо Сангвиньи","Баттиста ди Бьяджо Сангуиньи","Сангвиньи","Battista di Biagio Sanguigni"],"bio":["Кливленд называет годы активности Баттисты ди Бьяджо Сангвиньи — 1393–1451. Других биографических сведений в выбранной записи нет.","Его кливлендская картина точно датирована надписью 1419 года, и именно поэтому она полезна как опорный пример."],"technique":["Монументальная Богоматерь сидит на богатом престоле и держит Младенца. Выше показан воскресший Христос в небесах с книгой, на которой написаны альфа и омега — первая и последняя буквы греческого алфавита, знак Христа как начала и конца всего.","Итальянская надпись сообщает: картина сделана для Антонио ди Доменико Джуньи ради упокоения его души в 1419 году."],"innovation":"Музей использует эту доску, чтобы объяснить сдвиг в итальянской живописи. В XIV веке она подчёркивала небесную сторону веры и помещала священные фигуры на эфирный золотой фон; примерно через сто лет мастера стали подчёркивать земную сторону и помещать их в натуралистические пейзажи, чтобы святые казались ближе верующим.","features":["Золотой фон: символическое, а не повествовательное изображение.","Престол: Мария на богатом троне.","Воскресший Христос над сценой: книга с альфой и омегой.","Надпись-дата: заказчик и 1419 год названы прямо.","Переходная манера: золото ещё сохраняется внутри XV века."],"caution":"Картина не изображает одного момента времени: это символический образ, а не сцена. Золотой фон не доказывает, что работа «готическая»: надпись датирует её 1419 годом, то есть кватроченто.","sources":[["Cleveland Museum of Art: Virgin and Child Enthroned","https://clevelandart.org/art/1954.834"]],"works":[{"key":"cma:132367","date":"1419","image":"https://openaccess-cdn.clevelandart.org/1954.834/1954.834_web.jpg","zoom":"https://openaccess-cdn.clevelandart.org/1954.834/1954.834_print.jpg","source":"https://clevelandart.org/art/1954.834","museum":"Cleveland Museum of Art","originalTitle":"Virgin and Child Enthroned","medium":"tempera and gold on wood","title":"Мадонна с Младенцем на престоле","look":"Найди воскресшего Христа вверху с книгой, где написаны альфа и омега, и итальянскую надпись о заказчике и 1419 годе. Музей противопоставляет такой золотой фон более поздним натуралистическим пейзажам."}]},"giovanni_francesco_toscani":{"name":"Джованни Франческо Тоскани","latin":"Giovanni Francesco Toscani","life":"ок. 1380–1430","tag":"Италия · раннее кватроченто","aliases":["Джованни Франческо Тоскани","Тоскани","Giovanni Francesco Toscani"],"bio":["Кливленд указывает годы жизни Джованни Франческо Тоскани — около 1380–1430. Остальные сведения о нём в выбранной записи отсутствуют.","Его кливлендская вещь важна не как «станковая картина», а как расписанная мебель для свадьбы."],"technique":["Это панель с кассоне — деревянного сундука для хранения одежды, обязательного предмета обстановки в итальянских домах эпохи Возрождения. Сундуки часто делали парами и богато украшали росписью и золочёными профилями, обычно по случаю свадьбы.","Сцена показывает конец палио — конной скачки по улицам Флоренции в праздник Иоанна Крестителя, 24 июня. Вторая сторона сундука с шествием знамён палио хранится в музее Барджелло."],"innovation":"Тоскани показывает, что живопись раннего кватроченто служила не только алтарю. Картина на свадебном сундуке фиксировала памятное событие, а сам предмет напоминал о браке между семьями Фини и Альдобрандини в 1418 году.","features":["Сундук-кассоне: живопись на мебели.","Городской праздник: палио в день Иоанна Крестителя.","Свадебный заказ: брак Фини и Альдобрандини в 1418 году.","Золото и темпера по дереву.","Парные панели: вторая часть хранится в музее Барджелло."],"caution":"Не принимай кассоне за обычную картину: первоначальная функция предмета — мебель. Кватроченто означает итальянский XV век, а не обязательное появление ренессансной перспективы.","sources":[["Cleveland Museum of Art: Panel from a Cassone: The Race of the Palio in the Streets of Florence","https://clevelandart.org/art/1916.801"]],"works":[{"key":"cma:97165","date":"1418","image":"https://openaccess-cdn.clevelandart.org/1916.801/1916.801_web.jpg","zoom":"https://openaccess-cdn.clevelandart.org/1916.801/1916.801_print.jpg","source":"https://clevelandart.org/art/1916.801","museum":"Cleveland Museum of Art","originalTitle":"Panel from a Cassone: The Race of the Palio in the Streets of Florence","medium":"tempera and gold on wood","title":"Скачки Палио во Флоренции","look":"Панель с лицевой стороны свадебного сундука показывает конец палио на улицах Флоренции. Музей рассказывает, что вторая часть с шествием знамён хранится в музее Барджелло."}]},"jacopo_del_sellaio":{"name":"Якопо дель Селлайо","latin":"Jacopo del Sellaio","life":"ок. 1441–1493","tag":"Италия · кватроченто","aliases":["Якопо дель Селлайо","Селлайо","Jacopo del Sellaio"],"bio":["Кливленд указывает годы жизни Якопо дель Селлайо — около 1441–1493. Биографические сведения в выбранной записи ограничены.","В нашем собрании он представлен панелью от свадебного сундука."],"technique":["Панель была лицевой стороной сундука для невесты, затем её сняли с мебели и вставили в раму, как обычную картину.","Слева этрусская пророчица Танаквиль предвидит въезд мужа в Рим. По дороге орёл унёс его шляпу и вернул, когда они приблизились к городу; Танаквиль истолковала это как добрый знак."],"innovation":"Селлайо показывает, как античная история входила в домашний быт: триумфальные шествия, близкие к античным саркофагам, были популярным сюжетом для сундуков невесты. Танаквиль здесь — образец заботливой, преданной жены.","features":["Сундук невесты: живопись на мебели, затем рама.","Античный сюжет: Танаквиль и въезд в Рим.","Добрый знак: орёл возвращает шляпу.","Триумфальное шествие: тема, связанная с античными саркофагами.","Нравоучение: образец преданной жены."],"caution":"Картина первоначально была частью мебели, а не станковым произведением. Сюжет античный, но сама работа относится к итальянскому XV веку.","sources":[["Cleveland Museum of Art: Tarquinius Priscus Entering Rome","https://clevelandart.org/art/1942.646"]],"works":[{"key":"cma:122350","date":"c. 1470","image":"https://openaccess-cdn.clevelandart.org/1942.646/1942.646_web.jpg","zoom":"https://openaccess-cdn.clevelandart.org/1942.646/1942.646_print.jpg","source":"https://clevelandart.org/art/1942.646","museum":"Cleveland Museum of Art","originalTitle":"Tarquinius Priscus Entering Rome","medium":"tempera on wood, mounted on canvas","title":"Тарквиний Древний вступает в Рим","look":"Слева найди Танаквиль, пророчащую въезд мужа. Музей рассказывает про орла, который унёс шляпу и вернул её у ворот города."}]},"carolino_da_viterbo":{"name":"Каролино да Витербо","latin":"Carolino da Viterbo","life":"XV век","tag":"Италия · кватроченто","aliases":["Каролино да Витербо","Карролино да Витербо","Carolino da Viterbo"],"bio":["Кливленд называет Каролино да Витербо итальянским мастером, но не приводит годов жизни.","Его кливлендская доска датирована около 1450 года."],"technique":["Младенец держит в правой руке стебель роз. Красота и аромат роз символизируют небо, а шипы напоминают о терновом венце и страдании Христа. Птица в левой руке — знак человеческой души.","Нимбы с латинскими надписями называют фигуры и помогают организовать композицию. На нимбе Богоматери: «Радуйся, благодатная»; наверху — одно из её популярных имён «Милосердная Мать»."],"innovation":"Доска показывает, как письмо на золоте работало как система знаков: надписи на нимбах называют персонажей, а розы и птица добавляют значения. Это язык символов, а не только изображение людей.","features":["Нимбы с надписями: имена и титулы Христа, Иеронима, Екатерины.","Розы: небо и терновый венец.","Птица: душа человека.","Золотой фон и темпера по дереву.","Святые Иероним и Екатерина Александрийская рядом с Богоматерью."],"caution":"Годы жизни мастера музей не указывает, поэтому «XV век» дано по дате картины (около 1450).","sources":[["Cleveland Museum of Art: Virgin and Child with Saint Jerome and Saint Catherine of Alexandria","https://clevelandart.org/art/1956.719"]],"works":[{"key":"cma:134237","date":"c. 1450","image":"https://openaccess-cdn.clevelandart.org/1956.719/1956.719_web.jpg","zoom":"https://openaccess-cdn.clevelandart.org/1956.719/1956.719_print.jpg","source":"https://clevelandart.org/art/1956.719","museum":"Cleveland Museum of Art","originalTitle":"Virgin and Child with Saint Jerome and Saint Catherine of Alexandria","medium":"tempera and gold on wood panel","title":"Мадонна с Младенцем, Иеронимом и Екатериной","look":"Найди стебель роз в руке Младенца и птицу в другой руке. Прочитай, как надписи на нимбах называют героев и титулы Марии."}]},"ugolino_di_nerio":{"name":"Уголино ди Нерио","latin":"Ugolino di Nerio","life":"XIV век","tag":"Италия · треченто","aliases":["Уголино ди Нерио","Угголино ди Нерио","Ugolino di Nerio"],"bio":["Кливленд называет Уголино ди Нерио итальянским мастером и не приводит годов жизни. Его кливлендская доска датирована около 1320 года.","Больше музейная запись о художнике ничего не сообщает."],"technique":["В средневековых итальянских церквях расписные алтари были центром внимания верующих во время обрядов. Фигуры Иисуса, Марии и восьми святых обрамлены золотым фоном, который должен был блестеть в мерцающем свете свечей."],"innovation":"Работа напоминает, что готические и дученто-треченто алтари предназначались для света свечей и обряда. Золото здесь не декор в нейтральном смысле, а часть переживания службы.","features":["Золотой фон: блеск при свечах.","Многофигурный алтарь: Мария, Христос и восемь святых.","Храмовая функция: центр внимания верующих.","Темпера и золото по дереву.","Итальянская доска: мастер назван итальянским."],"caution":"Музейная запись короткая и не называет годы жизни и школу; дата дана по картине (около 1320).","sources":[["Cleveland Museum of Art: Virgin and Child with Saints","https://clevelandart.org/art/1961.40"]],"works":[{"key":"cma:136922","date":"c. 1320","image":"https://openaccess-cdn.clevelandart.org/1961.40/1961.40_web.jpg","zoom":"https://openaccess-cdn.clevelandart.org/1961.40/1961.40_print.jpg","source":"https://clevelandart.org/art/1961.40","museum":"Cleveland Museum of Art","originalTitle":"Virgin and Child with Saints","medium":"tempera and gold on wood panel","title":"Мадонна с Младенцем и святыми","look":"Посчитай фигуры: Иисус, Мария и восемь святых. Представь, как золотой фон мерцал в свете свечей в церкви."}]},"caterino_veneziano":{"name":"Катерино Венециано","latin":"Caterino Veneziano","life":"работал 1362–1382","tag":"Италия · Венеция, треченто","aliases":["Катерино Венециано","Caterino Veneziano"],"bio":["Кливленд называет годы активности Катерино Венециано — 1362–1382. Он венецианский мастер середины и второй половины XIV века.","Его кливлендская доска датирована концом 1370-х годов."],"technique":["Мадонна сидит на земле и кормит Младенца. Такой тип называется «Мадонна Смирения»: Мария сидит на земле только с подушкой, в отличие от обычного изображения на троне. Лат. humilitas — смирение."],"innovation":"Тип «Мадонны Смирения» показывает перемену в благочестии: добродетель смирения проповедовал особенно Франциск Ассизский, и в живописи она появилась с 1350-х годов, после Чёрной смерти.","features":["Мадонна на земле: подушка вместо трона.","Кормление Младенца: интимный, человечный образ.","Смирение: humilitas как добродетель.","Влияние Франциска: идея пришла из францисканской проповеди.","После Чёрной смерти: тип распространился с 1350-х."],"caution":"Не называй любую Мадонну с Младенцем «Смирением»: музей использует термин только для изображения Марии на земле, без трона.","sources":[["Cleveland Museum of Art: Madonna of Humility","https://clevelandart.org/art/1963.500"]],"works":[{"key":"cma:139727","date":"late 1370s","image":"https://openaccess-cdn.clevelandart.org/1963.500/1963.500_web.jpg","zoom":"https://openaccess-cdn.clevelandart.org/1963.500/1963.500_print.jpg","source":"https://clevelandart.org/art/1963.500","museum":"Cleveland Museum of Art","originalTitle":"Madonna of Humility","medium":"tempera and gold on wood panel","title":"Мадонна Смирения","look":"Найди подушку и землю под Марией: она не на троне. Музей связывает этот тип с проповедью Франциска и с годами после Чёрной смерти."}]},"andrea_da_firenze":{"name":"Андреа да Фиренце","latin":"Andrea da Firenze","life":"дата в записи — 1379","tag":"Италия · Флоренция и Сиена, треченто","aliases":["Андреа да Фиренце","Andrea da Firenze"],"bio":["Кливленд называет Андреа да Фиренце художником, работавшим во Флоренции и Сиене после Чёрной смерти, начавшейся в конце 1340-х годов. В скобках к имени стоит только год 1379.","Кливлендская доска датирована 1360-ми годами."],"technique":["Панель, вероятно, входила в небольшой алтарь для частной молитвы. Распятие написано темперой и золотом по дереву (грецкому ореху)."],"innovation":"Музей подчёркивает эмоцию: работы мастера, как и другие вещи этого тревожного времени, насыщены чувством. Это объясняет, почему для треченто важны не только золото и символы, но и переживание после эпидемии.","features":["Алтарь для частной молитвы.","Распятие: центральный сюжет.","Эмоциональный заряд: образ времени после Чёрной смерти.","Деревянная основа: грецкий орех.","Золото и темпера: техника доски."],"caution":"Дата «1379» в записи Кливленда указана рядом с именем и не описывает саму картину; ориентируйся на «1360-е» как дату панели.","sources":[["Cleveland Museum of Art: The Crucifixion","https://clevelandart.org/art/1916.776"]],"works":[{"key":"cma:97136","date":"c. 1360s","image":"https://openaccess-cdn.clevelandart.org/1916.776/1916.776_web.jpg","zoom":"https://openaccess-cdn.clevelandart.org/1916.776/1916.776_print.jpg","source":"https://clevelandart.org/art/1916.776","museum":"Cleveland Museum of Art","originalTitle":"The Crucifixion","medium":"tempera and gold on wood (walnut)","title":"Распятие","look":"Панель, вероятно, из небольшого алтаря для частной молитвы. Музей связывает её эмоциональность с временем после Чёрной смерти."}]},"matteo_di_giovanni":{"name":"Маттео ди Джованни","latin":"Matteo di Giovanni","life":"ок. 1430–1495","tag":"Италия · кватроченто","aliases":["Маттео ди Джованни","Matteo di Giovanni"],"bio":["Чикагский музей указывает годы жизни Маттео ди Джованни — около 1430–1495. В нашем собрании от него «Сон святого Иеронима» 1476 года.","Больше биографических сведений выбранная запись не содержит."],"technique":["Картина и её пара «Видение святого Августина» показывают сцены из жизни Иеронима — учёного, которому приписывают перевод Библии с древнееврейского на латынь, более известный язык того времени.","Первая сцена — сон Иеронима о наказании небесным советом за то, что он предпочитал античные тексты Библии. Во второй Августин пишет надгробное слово Иерониму, и ему является видение святого вместе с Иоанном Крестителем."],"innovation":"Парные картины показывают, как рассказ о святом разворачивался на нескольких досках: каждая сцена объясняет одну сторону его жизни, а пара вместе даёт повествование.","features":["Парные панели: «Сон Иеронима» и «Видение Августина».","Повествовательный эпизод: сон о небесном суде.","Тема учёности: перевод Библии на латынь.","Святой в видении: Иоанн Креститель.","Темпера по доске: 1476 год."],"caution":"Кватроченто — итальянский XV век, а не обязательное отсутствие средневековых приёмов. Вторая панель пары в чикагской записи упоминается, но в игру не включена.","sources":[["Art Institute of Chicago: The Dream of Saint Jerome","https://www.artic.edu/artworks/16179"]],"works":[{"key":"aic:16179","date":"1476","image":"https://www.artic.edu/iiif/2/336a83f3-c184-add1-ee03-f295aa97a0b0/full/843,/0/default.jpg","zoom":"https://www.artic.edu/iiif/2/336a83f3-c184-add1-ee03-f295aa97a0b0/full/1686,/0/default.jpg","source":"https://www.artic.edu/artworks/16179","museum":"Art Institute of Chicago","originalTitle":"The Dream of Saint Jerome","medium":"tempera on panel","title":"Сон святого Иеронима","look":"Музей объясняет сон Иеронима о небесном совете, который наказывает его за предпочтение античных текстов Библии. Сравни сюжет с парной сценой Августина."}]},"johann_koerbecke":{"name":"Иоганн Кёрбеке","latin":"Johann Koerbecke","life":"ок. 1420–1490","tag":"Германия · Мюнстер, поздняя готика","aliases":["Иоганн Кёрбеке","Кёрбеке","Йоханн Кёрбеке","Johann Koerbecke"],"bio":["Чикагский музей указывает годы жизни Иоганна Кёрбеке — около 1420–1490. Его главное произведение — алтарь бывшего цистерцианского аббатства Мариенфельд близ Мюнстера на северо-западе Германии.","Чикагская панель «Благовещение» — одна из восьми сцен из жизни Девы Марии на внутренней стороне створок этого алтаря; музей завершает её датировкой «не позднее 1457 года»."],"technique":["Створки обрамляли центр алтаря, где в праздничные дни при раскрытии выставляли мощи и золочёную статую Девы Марии с Младенцем. Золотые фоны и праздничная архитектура усиливали великолепие открытого алтаря.","Оборотная сторона створок, видимая в закрытом виде, была украшена более сдержанными сценами Страстей в натуралистических пейзажах."],"innovation":"Эта панель учит смотреть на картину как на часть конструкции с двумя состояниями: открытое великолепие и закрытая сдержанность. В конце XVII века ансамбль разобрали, а в начале XIX века створки распилили и панели рассеяли.","features":["Часть алтаря: восемь сцен жизни Марии.","Золото и архитектура: праздничная сторона.","Сдержанные Страсти: оборотная сторона.","Масло по дереву, переведено на холст.","Разобранный ансамбль: разрозненные панели."],"caution":"Золото само по себе не отличает готику от Возрождения. Панель сохранила только часть первоначального ансамбля: оборотные сцены разделены с лицевыми, а техника «масло по дереву, переведено на холст» сообщает о реставрационной истории.","sources":[["Art Institute of Chicago: The Annunciation","https://www.artic.edu/artworks/16333"]],"works":[{"key":"aic:16333","date":"Completed by 1457","image":"https://www.artic.edu/iiif/2/19b940dd-bb34-8ce7-601a-cb3fa1010f97/full/843,/0/default.jpg","zoom":"https://www.artic.edu/iiif/2/19b940dd-bb34-8ce7-601a-cb3fa1010f97/full/1686,/0/default.jpg","source":"https://www.artic.edu/artworks/16333","museum":"Art Institute of Chicago","originalTitle":"The Annunciation","medium":"oil on panel, transferred to canvas","title":"Благовещение","look":"Музей описывает панель как одну из восьми сцен жизни Девы Марии на внутренней стороне створок. Найди золотой фон и праздничную архитектуру: они усиливали великолепие открытого алтаря."}]}});

;
/* artists-batch-9.js */
window.registerPaintingArtists&&window.registerPaintingArtists({"el_greco":{"name":"Эль Греко","latin":"El Greco","life":"1541–1614","tag":"Испания · Толедо, маньеризм","aliases":["Эль Греко","Доменикос Теотокопулос","El Greco"],"bio":["Чикагский музей называет мастера греком, работавшим в Испании: он родился в 1541 году, а карьеру сделал в Толедо. «Вознесение Богоматери» (1577–1579) стало центральной картиной его первого крупного заказа — алтаря церкви монастыря Санто-Доминго-эль-Антигуо.","Монастырская церковь служила погребальным памятником богатой дворянки Доньи Марии де Сильва, поэтому вся программа заказа посвящена смерти и спасению."],"technique":["Чикагский музей описывает широкие свободные мазки, мерцающие оттенки, богатые цветовые гармонии и смелые композиции, которые должны были вызывать у зрителя молитвенный пыл. Фигуры сжаты в высоком узком формате: земная зона апостолов с резкими жестами и небесная зона спокойных ангелов.","Кливленд пишет, что «невесомые» фигуры, неожиданные сочетания цветов и смутная обстановка показывают интерес Эль Греко к духовности образов, а не к их конкретной реальности."],"innovation":"Музеи показывают двух Эль Греко: мастера больших алтарей и мастера небольших повторений. Чикагская картина «Святой Мартин и нищий» — небольшая реплика алтаря для частной капеллы Сан-Хосе в Толедо; такие уменьшенные версии помогали художнику выйти на более широкий рынок.","features":["Невесомые фигуры: тела вытянуты и словно парят.","Неожиданный цвет: сочетания тонов выражают духовность, а не предмет.","Свободный мазок: мерцающие блики вместо гладкой лепки.","Двухъярусная композиция: земная и небесная зоны.","Повторения: у «Святого Франциска» известно не меньше десятка версий."],"caution":"Мастерская Эль Греко делала версии и реплики; чикагскую работу «Святой Мартин и нищий» музей прямо называет небольшой репликой алтаря. Картины «мастерской Эль Греко» в игру не включены. Годы 1541–1614 — общие для чикагской и кливлендской записей.","sources":[["Cleveland Museum of Art: The Holy Family with Mary Magdalen","https://clevelandart.org/art/1926.247"],["Art Institute of Chicago: Saint Francis Kneeling in Meditation","https://www.artic.edu/artworks/21907"],["Art Institute of Chicago: The Assumption of the Virgin","https://www.artic.edu/artworks/87479"],["Art Institute of Chicago: Saint Martin and the Beggar","https://www.artic.edu/artworks/67362"]],"works":[{"key":"cma:108541","date":"c. 1590–95","image":"https://openaccess-cdn.clevelandart.org/1926.247/1926.247_web.jpg","zoom":"https://openaccess-cdn.clevelandart.org/1926.247/1926.247_print.jpg","source":"https://clevelandart.org/art/1926.247","museum":"Cleveland Museum of Art","originalTitle":"The Holy Family with Mary Magdalen","medium":"oil on canvas","title":"Святое семейство с Марией Магдалиной","look":"Музей отмечает невесомые фигуры, неожиданные сочетания цвета и смутную обстановку. Мария кормит Иисуса фруктами, которые держит Иосиф: яблоко — грехопадение, вишни — кровь Христа, персики — спасение, груши — сладость добродетели."},{"key":"aic:21907","date":"c. 1595–c. 1600","image":"https://www.artic.edu/iiif/2/b703b636-976c-b35b-8a8e-f8df3f5ba003/full/843,/0/default.jpg","zoom":"https://www.artic.edu/iiif/2/b703b636-976c-b35b-8a8e-f8df3f5ba003/full/1686,/0/default.jpg","source":"https://www.artic.edu/artworks/21907","museum":"Art Institute of Chicago","originalTitle":"Saint Francis Kneeling in Meditation","medium":"oil on canvas","title":"Святой Франциск на коленях в размышлении","look":"Музей перечисляет знаки святости: книга — учёба в благочестии, череп — неизбежность смерти. Зритель должен медитировать так же, как святой молится перед скульптурой Христа. Известно не менее двенадцати версий этой композиции."},{"key":"aic:87479","date":"1577–79","image":"https://www.artic.edu/iiif/2/47fd1564-93f5-f30b-7786-013421133b4a/full/843,/0/default.jpg","zoom":"https://www.artic.edu/iiif/2/47fd1564-93f5-f30b-7786-013421133b4a/full/1686,/0/default.jpg","source":"https://www.artic.edu/artworks/87479","museum":"Art Institute of Chicago","originalTitle":"The Assumption of the Virgin","medium":"oil on canvas","title":"Вознесение Богоматери","look":"Центральная картина первого крупного заказа Эль Греко. Найди две зоны: земную, где апостолы выражают разные эмоции, и небесную, где спокойные ангелы обращены к поднимающейся Марии."},{"key":"aic:67362","date":"c. 1597–c. 1600","image":"https://www.artic.edu/iiif/2/52098776-6e2e-9683-e258-7b1cec8660dd/full/843,/0/default.jpg","zoom":"https://www.artic.edu/iiif/2/52098776-6e2e-9683-e258-7b1cec8660dd/full/1686,/0/default.jpg","source":"https://www.artic.edu/artworks/67362","museum":"Art Institute of Chicago","originalTitle":"Saint Martin and the Beggar","medium":"oil on canvas","title":"Святой Мартин и нищий","look":"Небольшая реплика алтаря для частной капеллы Сан-Хосе в Толедо. Музей отмечает современные доспехи святого и стены Толедо на дальнем плане."}]},"lucas_cranach_the_elder":{"name":"Лукас Кранах Старший","latin":"Lucas Cranach the Elder","life":"1472–1553","tag":"Германия · северное Возрождение","aliases":["Лукас Кранах Старший","Лукас Кранах","Кранах Старший","Кранах","Lucas Cranach the Elder"],"bio":["Чикагский музей пишет, что большую часть своей долгой карьеры Кранах Старший был придворным живописцем курфюрста Саксонии. Он дружил с реформатором Мартином Лютером."],"technique":["Расположение Адама и Евы в чикагской паре, по словам музея, отражает влияние классицизирующего решения Альбрехта Дюрера на ту же тему, но стройные, извивающиеся фигуры Кранаха соответствуют придворным идеалам красоты своего времени.","«Распятие» 1538 года — тесная сцена с традиционными эпизодами вокруг креста: Мария в обмороке в левом углу, осуждающие и насмешники, солдаты, бросающие кости."],"innovation":"Кранах показывает северное Возрождение как придворное и протестантское искусство. Чикагский музей замечает, что в «Распятии» он усилил протестантский акцент на силе веры и личной ответственности: например, мальчик, который учится у старика у подножия центрального креста.","features":["Придворный стиль: стройные волнистые фигуры по моде двора.","Влияние Дюрера: расстановка Адама и Евы.","Повторение композиций: множество версий создавала мастерская.","Протестантские акценты: вера и личная ответственность.","Многофигурная сцена: «Распятие» с эпизодами жизни Христа."],"caution":"Музей прямо пишет, что пара «Адам» и «Ева» — одна из лучших из многих версий, созданных Кранахом и его мастерской. Поэтому читай «Кранах» как имя мастера и мастерской.","sources":[["Art Institute of Chicago: Adam","https://www.artic.edu/artworks/111718"],["Art Institute of Chicago: Eve","https://www.artic.edu/artworks/21668"],["Art Institute of Chicago: The Crucifixion","https://www.artic.edu/artworks/59856"]],"works":[{"key":"aic:111718","date":"1533–37","image":"https://www.artic.edu/iiif/2/0356e981-edc5-56ad-1a64-9ebdae3c5aab/full/843,/0/default.jpg","zoom":"https://www.artic.edu/iiif/2/0356e981-edc5-56ad-1a64-9ebdae3c5aab/full/1686,/0/default.jpg","source":"https://www.artic.edu/artworks/111718","museum":"Art Institute of Chicago","originalTitle":"Adam","medium":"oil on panel","title":"Адам","look":"Адам из лучшей пары, по оценке музея, среди многих версий темы. Сравни стройное волнистое тело с классицизирующим решением Дюрера."},{"key":"aic:21668","date":"1533–37","image":"https://www.artic.edu/iiif/2/b07c2b88-f2a2-4d0a-e401-ebf8d7928373/full/843,/0/default.jpg","zoom":"https://www.artic.edu/iiif/2/b07c2b88-f2a2-4d0a-e401-ebf8d7928373/full/1686,/0/default.jpg","source":"https://www.artic.edu/artworks/21668","museum":"Art Institute of Chicago","originalTitle":"Eve","medium":"oil on panel","title":"Ева","look":"Парная картина к «Адаму». Музей связывает вытянутые изящные фигуры с придворными идеалами красоты времени Кранаха."},{"key":"aic:59856","date":"1538","image":"https://www.artic.edu/iiif/2/f5eb11a2-945f-f7cb-9994-ab54e8f24804/full/843,/0/default.jpg","zoom":"https://www.artic.edu/iiif/2/f5eb11a2-945f-f7cb-9994-ab54e8f24804/full/1686,/0/default.jpg","source":"https://www.artic.edu/artworks/59856","museum":"Art Institute of Chicago","originalTitle":"The Crucifixion","medium":"oil on panel","title":"Распятие","look":"Найди обморок Марии в нижнем левом углу и солдат, бросающих кости, а также мальчика, который учится у старика у подножия центрального креста: музей видит в этом протестантский акцент."}]},"jacopo_bassano":{"name":"Якопо Бассано","latin":"Jacopo Bassano","life":"ок. 1510–1592","tag":"Италия · Венето, маньеризм","aliases":["Якопо Бассано","Бассано","Jacopo Bassano"],"bio":["Чикагский музей пишет, что почти всю рабочую жизнь Якопо Бассано провёл в родном небольшом городе Бассано-дель-Граппа на материке Венецианской республики."],"technique":["Богатые цвета и рельефные мазки музей считает характерными для современных ему живописцев Венеции. Он связывает работу с Тицианом и Паоло Веронезе: мерцающие блики оживляют одежды Марии и красный занавес.","Стройные пропорции головы и шеи Мадонны, напротив, музей считает характерными для искусственного и утончённого стиля маньеризма."],"innovation":"Картина соединяет венецианскую живописность (цвет, мазок, блики) с маньеристской вытянутостью фигуры. Это учебный пример перехода от высокого Возрождения к маньеризму.","features":["Богатый цвет: тёплые насыщенные тона.","Рельефный мазок: фактура видна.","Мерцающие блики: влияние Тициана и Веронезе.","Вытянутые пропорции: маньеристская шея и голова.","Небольшой город: мастер работал вне Венеции."],"caution":"Годы жизни приблизительны: около 1510–1592. Вторая чикагская запись с картиной около 1710 года в игру не включена.","sources":[["Art Institute of Chicago: Virgin and Child with the Young Saint John the Baptist","https://www.artic.edu/artworks/109323"]],"works":[{"key":"aic:109323","date":"1560–65","image":"https://www.artic.edu/iiif/2/5c9cfee1-4287-1494-dcf6-4a967c734a44/full/843,/0/default.jpg","zoom":"https://www.artic.edu/iiif/2/5c9cfee1-4287-1494-dcf6-4a967c734a44/full/1686,/0/default.jpg","source":"https://www.artic.edu/artworks/109323","museum":"Art Institute of Chicago","originalTitle":"Virgin and Child with the Young Saint John the Baptist","medium":"oil on canvas","title":"Мадонна с Младенцем и юным Иоанном Крестителем","look":"Найди блики на одеждах Марии и красный занавес, а затем шею и голову Мадонны: музей считает их вытянутые пропорции чертой маньеризма."}]},"master_of_the_holy_blood":{"name":"Мастер Святой Крови","latin":"Master of the Holy Blood","life":"работал около 1520","tag":"Нидерланды · Брюгге, северное Возрождение","aliases":["Мастер Святой Крови","Master of the Holy Blood"],"bio":["Кливленд пишет, что личность художника неизвестна. Его назвали по картине в капелле Святой Крови в Брюгге.","Брюгге процветал как международный торговый центр в XV и начале XVI века. Там жили иностранные купцы и банкиры, а вместе с бургундским двором они покровительствовали художникам и привлекали мастеров по меху, шляпам, ювелирным изделиям и золоту."],"technique":["Две картины с Екатериной и Варварой были створками алтаря, обрамлявшими утерянную центральную панель, возможно, со Святым семейством. Екатерина держит меч, которым её казнили; Варвара держит книгу и кольцо — знаки учёности и союза с Богом.","По легенде, кожаные ремни, которыми била Варвару, превратились в павлиньи перья."],"innovation":"Условное имя показывает, как искусствоведы работают с анонимами: мастера называют по главному произведению. Кливленд ставит его в ряд брюггских живописцев Яна ван Эйка, Петруса Кристуса, Ганса Мемлинга и Герарда Давида.","features":["Створки алтаря: две панели вокруг утерянного центра.","Атрибуты святых: меч Екатерины, книга и кольцо Варвары.","Павлиньи перья: легенда о ремнях Варвары.","Брюгге: торговый город и художественный центр.","Анонимный мастер: имя по картине в капелле."],"caution":"Не принимай условное имя за имя человека: личность мастера неизвестна. Кливлендская запись «пара» (1942.633) в игру не включена, чтобы не дублировать две створки.","sources":[["Cleveland Museum of Art: Saint Catherine","https://clevelandart.org/art/1942.633.1"],["Cleveland Museum of Art: Saint Barbara","https://clevelandart.org/art/1942.633.2"]],"works":[{"key":"cma:122336","date":"c. 1520","image":"https://openaccess-cdn.clevelandart.org/1942.633.1/1942.633.1_web.jpg","zoom":"https://openaccess-cdn.clevelandart.org/1942.633.1/1942.633.1_print.jpg","source":"https://clevelandart.org/art/1942.633.1","museum":"Cleveland Museum of Art","originalTitle":"Saint Catherine","medium":"tempera on wood panel","title":"Святая Екатерина","look":"Створка алтаря: Екатерина держит меч, которым её казнили. Музей предполагает, что центральная утерянная панель могла показывать Святое семейство."},{"key":"cma:122337","date":"c. 1520","image":"https://openaccess-cdn.clevelandart.org/1942.633.2/1942.633.2_web.jpg","zoom":"https://openaccess-cdn.clevelandart.org/1942.633.2/1942.633.2_print.jpg","source":"https://clevelandart.org/art/1942.633.2","museum":"Cleveland Museum of Art","originalTitle":"Saint Barbara","medium":"tempera on wood panel","title":"Святая Варвара","look":"Парная створка: Варвара держит книгу и кольцо, знаки учёности и союза с Богом. По легенде, ремни, которыми её били, превратились в павлиньи перья."}]},"hans_memling":{"name":"Ганс Мемлинг","latin":"Hans Memling","life":"ок. 1430–1494","tag":"Нидерланды · Брюгге, северное Возрождение","aliases":["Ганс Мемлинг","Мемлинг","Hans Memling"],"bio":["Кливленд пишет, что Мемлинг родился близ Франкфурта в Германии и около 1465 года поселился в Брюгге, где стал известен мастерством и работал для бургундского двора. После его смерти в 1494 году ведущим брюггским мастером стал Герард Давид."],"technique":["Чикагская «Мадонна с Младенцем» была левой частью диптиха; справа находился портрет молящегося мужчины. Диптих закрывался, и его внешняя сторона с изображением Антония Падуанского написана гризайлью — монохромной техникой, имитирующей скульптуру.","Музей отмечает детали: сандалия Антония переступает край рамы, а в выпуклом зеркале за Марией отражаются двое детей, возможно, дети заказчика."],"innovation":"Диптих работал как посредник между миром зрителя и священным пространством: гризайль внешних створок и «выход» ноги святого за раму подводили к молитвенной встрече. Такие портретные диптихи были популярны после 1400 года и исчезли около 1530-х.","features":["Гризайль: монохромные створки как скульптура.","Выпуклое зеркало: отражение детей в сцене.","Рамка как порог: нога святого выходит за край.","Диптих: Мадонна и молящийся донатор.","Тонкое письмо маслом по дереву."],"caution":"Кливлендская «Мадонна с Младенцем» (1934.29), по мнению музея, написана, видимо, членом мастерской Мемлинга, поэтому в игру она не включена. Портретная часть чикагского диптиха плохо сохранилась.","sources":[["Art Institute of Chicago: Virgin and Child","https://www.artic.edu/artworks/16295"]],"works":[{"key":"aic:16295","date":"c. 1485","image":"https://www.artic.edu/iiif/2/72083f93-6fe2-bfa8-b9a0-82e50c123015/full/843,/0/default.jpg","zoom":"https://www.artic.edu/iiif/2/72083f93-6fe2-bfa8-b9a0-82e50c123015/full/1686,/0/default.jpg","source":"https://www.artic.edu/artworks/16295","museum":"Art Institute of Chicago","originalTitle":"Virgin and Child","medium":"oil on panel","title":"Мадонна с Младенцем","look":"Найди выпуклое зеркало за Марией: в нём отражаются двое детей. Музей объясняет, что картина и портрет молящегося мужчины раньше образовывали диптих, а внешняя сторона была написана гризайлью."}]},"gerard_david":{"name":"Герард Давид","latin":"Gerard David","life":"ок. 1460–1523","tag":"Нидерланды · Брюгге, северное Возрождение","aliases":["Герард Давид","Геррит Давид","Gerard David"],"bio":["Кливленд пишет, что Герард Давид родился в Ауденвотере (ныне провинция Утрехт) и провёл зрелую карьеру в Брюгге, где был членом гильдии живописцев. После смерти Ганса Мемлинга в 1494 году он стал ведущим живописцем религиозных панелей Брюгге. Он был и миниатюристом."],"technique":["Чикагское «Оплакивание Христа» входило в Алтарь святой Анны — серию из десяти панелей в архитектурной раме, написанную Давидом и его мастерской на экспорт в Испанию. Мария, Иоанн и Мария Магдалина грациозно склоняются над телом, на щеках слёзы.","Кливлендское «Рождество» показывает ангела, благовествующего пастухам, и Иерусалим вдали в облике северного средневекового города."],"innovation":"Давид превращает большие заказы в рассказ для молящегося: центральная нижняя панель алтаря стояла за престолом, чтобы при благословении евхаристии напоминать о жертве Христа.","features":["Алтарь на экспорт: панели для Испании.","Грациозные фигуры у тела Христа.","Северный средневековый город вместо Иерусалима.","Ангел и пастухи вдали.","Возможный портрет заказчика: голова Иосифа."],"caution":"Некоторые учёные видят в голове Иосифа на «Рождестве» портрет заказчика; музей подаёт это как предположение. Даты рождения расходятся: около 1460 (Чикаго) и 1450/60 (Кливленд).","sources":[["Cleveland Museum of Art: The Nativity","https://clevelandart.org/art/1958.320"],["Art Institute of Chicago: Lamentation over the Body of Christ","https://www.artic.edu/artworks/16261"]],"works":[{"key":"cma:135311","date":"c. 1485–90","image":"https://openaccess-cdn.clevelandart.org/1958.320/1958.320_web.jpg","zoom":"https://openaccess-cdn.clevelandart.org/1958.320/1958.320_print.jpg","source":"https://clevelandart.org/art/1958.320","museum":"Cleveland Museum of Art","originalTitle":"The Nativity","medium":"oil on wood panel","title":"Рождество","look":"Вдали ангел объявляет пастухам о рождении Христа, один из них уже у яслей. Найди Иерусалим как северный средневековый город и голову Иосифа, в которой некоторые учёные видят портрет заказчика."},{"key":"aic:16261","date":"c. 1500","image":"https://www.artic.edu/iiif/2/fd1a9c27-d95b-d8e7-209c-5492d9eb6e92/full/843,/0/default.jpg","zoom":"https://www.artic.edu/iiif/2/fd1a9c27-d95b-d8e7-209c-5492d9eb6e92/full/1686,/0/default.jpg","source":"https://www.artic.edu/artworks/16261","museum":"Art Institute of Chicago","originalTitle":"Lamentation over the Body of Christ","medium":"oil on panel","title":"Оплакивание Христа","look":"Центральная нижняя панель Алтаря святой Анны. Мария, Иоанн и Мария Магдалина склоняются над телом Христа со слезами на щеках; панель стояла за престолом."}]},"agnolo_bronzino":{"name":"Аньоло Бронзино","latin":"Agnolo Bronzino","life":"1503–1572","tag":"Италия · Флоренция, маньеризм","aliases":["Аньоло Бронзино","Бронзино","Agnolo Bronzino"],"bio":["Кливленд пишет, что Бронзино был придворным живописцем Козимо I Медичи, герцога Флоренции."],"technique":["«Портрет женщины» небольшой по размеру, но монументальный. Простой фон усиливает величественность. Рука, прижатая к груди с изящно разведёнными пальцами, восходит к древнегреческой позе скромности и подчёркивает благопристойность знатной женщины.","Модель носит льняную пелерину с тонкой вышивкой и манжеты с кружевной отделкой."],"innovation":"Как и в большинстве придворных портретов, Бронзино подчёркивает богатство, положение и придворную утончённость сильнее, чем личность и индивидуальное выражение.","features":["Придворная холодность: статус важнее характера.","Простой фон: монументальность при малом размере.","Античный жест: рука на груди.","Богатые детали: вышивка и кружево.","Неизвестная модель: связь с двором Медичи вероятна."],"caution":"Личность модели достоверно не установлена; музей говорит только, что она, вероятно, связана с двором Медичи. Чикагская «Мадонна» круга Бронзино в игру не включена: её авторство оспаривается.","sources":[["Cleveland Museum of Art: Portrait of a Woman","https://clevelandart.org/art/1972.121"]],"works":[{"key":"cma:146469","date":"c. 1550","image":"https://openaccess-cdn.clevelandart.org/1972.121/1972.121_web.jpg","zoom":"https://openaccess-cdn.clevelandart.org/1972.121/1972.121_print.jpg","source":"https://clevelandart.org/art/1972.121","museum":"Cleveland Museum of Art","originalTitle":"Portrait of a Woman","medium":"oil on wood","title":"Портрет женщины","look":"Найди руку, прижатую к груди, с разведёнными пальцами, и вышитую льняную пелерину. Музей объясняет, что фон намеренно прост, а акцент сделан на статусе, а не на личности."}]},"hans_baldung":{"name":"Ганс Бальдунг","latin":"Hans Baldung","life":"1484/85–1545","tag":"Германия · северное Возрождение","aliases":["Ганс Бальдунг","Бальдунг","Hans Baldung"],"bio":["Кливленд пишет, что Бальдунг был одновременно живописцем и гравёром и считается одним из самых одарённых учеников Альбрехта Дюрера."],"technique":["«Месса святого Григория» 1511 года была частью алтаря, заказанного Эрхардом Кёнигом, членом благотворительного орденского братства, для монастыря близ Страсбурга. Кёниг стоит справа с мальтийским крестом.","Григорий в облачении преклоняет колени в центре, священники рядом поражены. Согласно легенде, вера папы была вознаграждена видением Христа со знаками Страстей."],"innovation":"Картина показывает алтарную живопись как документ веры и заказа: заказчик изображён внутри сцены, а створки алтаря с Иоанном Евангелистом и Иоанном Крестителем находятся в Нью-Йорке и Вашингтоне.","features":["Ученик Дюрера: живописец и гравёр.","Видение Христа: знаки Страстей.","Заказчик в сцене: Эрхард Кёниг с мальтийским крестом.","Масло и темпера по дереву.","Разделённый алтарь: створки в Нью-Йорке и Вашингтоне."],"caution":"Сюжет — легенда о папе конца VI века, а картина написана в 1511 году. Створки алтаря с двумя Иоаннами хранятся в Нью-Йорке и Вашингтоне, поэтому центральная сцена показана отдельно.","sources":[["Cleveland Museum of Art: The Mass of Saint Gregory","https://clevelandart.org/art/1952.112"]],"works":[{"key":"cma:129220","date":"1511","image":"https://openaccess-cdn.clevelandart.org/1952.112/1952.112_web.jpg","zoom":"https://openaccess-cdn.clevelandart.org/1952.112/1952.112_print.jpg","source":"https://clevelandart.org/art/1952.112","museum":"Cleveland Museum of Art","originalTitle":"The Mass of Saint Gregory","medium":"oil and tempera on wood","title":"Месса святого Григория","look":"Найди Григория на коленях в центре, священников рядом и заказчика Эрхарда Кёнига справа с мальтийским крестом. Музей рассказывает легенду о видении Христа со знаками Страстей."}]},"hans_holbein_the_younger":{"name":"Ганс Гольбейн Младший","latin":"Hans Holbein the Younger","life":"1497/98–1543","tag":"Германия, Швейцария и Англия · северное Возрождение","aliases":["Ганс Гольбейн Младший","Гольбейн Младший","Гольбейн","Hans Holbein the Younger"],"bio":["Кливленд называет Гольбейна немецким художником, работавшим в Англии и Швейцарии. Его кливлендская картина датирована около 1532 года."],"technique":["Картина «Терминус — эмблема Эразма» объединяет черты Эразма Роттердамского (около 1466–1536) с римским богом границ Терминусом, который не уступил Юпитеру и остался на вершине Капитолийского холма.","Эразм принял Терминуса и девиз «Я не уступаю никому» (concedo nulli) как личный символ верности и стойкости."],"innovation":"Работа показывает гуманизм в картине: Гольбейн сливает портретные черты учёного и античный образ, чтобы выразить идею, а не просто сходство.","features":["Эмблема вместо портрета: образ и символ слиты.","Античный бог: Терминус как бог границ.","Девиз: concedo nulli.","Гуманизм: идеи античной литературы.","Масло по дереву."],"caution":"Это не обычный портрет Эразма: музей говорит, что Гольбейн «смешивает» его черты с Терминусом. Не принимай изображение за документальное сходство.","sources":[["Cleveland Museum of Art: Terminus, the Device of Erasmus","https://clevelandart.org/art/1971.166"]],"works":[{"key":"cma:145960","date":"c. 1532","image":"https://openaccess-cdn.clevelandart.org/1971.166/1971.166_web.jpg","zoom":"https://openaccess-cdn.clevelandart.org/1971.166/1971.166_print.jpg","source":"https://clevelandart.org/art/1971.166","museum":"Cleveland Museum of Art","originalTitle":"Terminus, the Device of Erasmus","medium":"oil on wood","title":"Термин — эмблема Эразма","look":"Музей поясняет: Гольбейн слил черты Эразма с римским богом границ Терминусом. Найди эмблему и вспомни девиз «Я не уступаю никому»."}]},"robert_campin":{"name":"Робер Кампен","latin":"Robert Campin","life":"1375/79–1444","tag":"Нидерланды · Турне, раннее нидерландское искусство","aliases":["Робер Кампен","Роберт Кампен","Кампен","Robert Campin"],"bio":["Кливленд пишет, что Кампен около 1405–1406 года поселился в Турне как свободный мастер гильдии живописцев, а в 1410 году купил гражданство, что говорит о рождении в другом месте."],"technique":["Кливленд считает, что, хотя Кампен многим обязан современным ему миниатюристам, он проявил больше реалистичной наблюдательности, чем любой живописец до него. Он был одним из первых, кто экспериментировал с маслом вместо яичной темперы ради яркого цвета.","На створке с Иоанном Крестителем белая ткань напоминает о новообращённых христианах, а флаг с красным крестом символизирует воскресение. Фон — роскошный золотой узорный шёлк."],"innovation":"Кампен показывает, как нидерландская живопись переходит от яичной темперы к маслу и к более точному наблюдению, не порывая при этом с традицией роскошной ткани и золота.","features":["Реалистичная наблюдательность: зоркость к деталям.","Масляные краски: яркий цвет.","Роскошная ткань: золотой узорный шёлк.","Символы: флаг с красным крестом.","Обрезанная створка: картина урезана снизу."],"caution":"Створка обрезана снизу и первоначально показывала святого в полный рост. Годы рождения указаны приблизительно: 1375/79.","sources":[["Cleveland Museum of Art: John the Baptist","https://clevelandart.org/art/1966.238"]],"works":[{"key":"cma:142476","date":"c. 1410","image":"https://openaccess-cdn.clevelandart.org/1966.238/1966.238_web.jpg","zoom":"https://openaccess-cdn.clevelandart.org/1966.238/1966.238_print.jpg","source":"https://clevelandart.org/art/1966.238","museum":"Cleveland Museum of Art","originalTitle":"John the Baptist","medium":"oil on oak panel","title":"Иоанн Креститель","look":"Музей отмечает белую ткань, флаг с красным крестом и золотой узорный шёлк фона. Работа обрезана снизу; вероятно, это правая створка триптиха с центральной Мадонной."}]},"petrus_christus":{"name":"Петрус Кристус","latin":"Petrus Christus","life":"ок. 1410–1475/76","tag":"Нидерланды · Брюгге, раннее нидерландское искусство","aliases":["Петрус Кристус","Кристус","Petrus Christus"],"bio":["Кливленд называет Кристуса живописцем Брюгге, вероятным учеником и преемником Яна ван Эйка. Работы Кристуса часто путали с работами ван Эйка. После его смерти следующим великим живописцем Брюгге стал Ганс Мемлинг."],"technique":["Кливленд пишет, что общий стиль картины близок к кругу ван Эйка, а лицо и плащ святого типичны для последователя ван Эйка Петруса Кристуса. Он показывает Иоанна Крестителя одиноким монументальным образом без обычной власяницы и других отсылок к жизни.","Эта трактовка восходит к монументальному образу Иоанна Клауса Слютера на портале Шанмоля и к миниатюристам при дворе Филиппа Смелого и Жана Беррийского. Иоанн держит Агнца Божия — знак жертвы Христа."],"innovation":"Картина показывает преемственность в брюггской живописи: от ван Эйка к Кристусу и затем к Мемлингу. Фигура святого монументальна и изолирована.","features":["Монументальный святой: одинокая фигура в пейзаже.","Агнец Божий: знак жертвы Христа.","Без власяницы: отсылки к жизни убраны.","Круг ван Эйка: лицо и плащ.","Масло по дереву."],"caution":"Музей формулирует осторожно: стиль «предполагает» автора из круга ван Эйка и «типичен» для Кристуса. Его работы часто путали с работами ван Эйка.","sources":[["Cleveland Museum of Art: Saint John the Baptist in a Landscape","https://clevelandart.org/art/1979.80"]],"works":[{"key":"cma:149768","date":"c. 1445","image":"https://openaccess-cdn.clevelandart.org/1979.80/1979.80_web.jpg","zoom":"https://openaccess-cdn.clevelandart.org/1979.80/1979.80_print.jpg","source":"https://clevelandart.org/art/1979.80","museum":"Cleveland Museum of Art","originalTitle":"Saint John the Baptist in a Landscape","medium":"oil on panel","title":"Иоанн Креститель в пейзаже","look":"Святой показан без власяницы, как монументальная фигура с Агнцем Божиим. Музей связывает лицо и плащ с манерой Петруса Кристуса, а образ — с традицией Слютера и придворных миниатюристов."}]}});

;
/* artists-batch-10.js */
(()=>{'use strict';
const rows=[
['tintoretto','Тинторетто','Tintoretto','1518–1594','aic:10509','Италия · чинквеченто','Якопо Робусти, известный как Тинторетто, назван в чикагской записи итальянским художником 1518–1594 годов.','В сцене испытания Истинного Креста смелые обобщённые мазки быстро передают позу и движение.','История Елены показана не мелкой отделкой, а энергией кисти. Это наблюдение относится к данной небольшой картине.','Смелый мазок|Обобщённая фигура|Движение|Небольшой повествовательный формат','Связь с большим циклом о Елене музей считает возможной, а не доказанной.','По легенде Елена определяет Истинный Крест по его способности воскрешать умерших. Смотри, как несколькими мазками переданы позы.'],
['pontormo','Якопо Понтормо','Jacopo da Pontormo','1494–1557','aic:110759','Италия · Флоренция, XVI век','Чикаго называет художника Якопо Карруччи, известным как Понтормо.','Портрет Алессандро Медичи — подготовительный этюд для более крупных парадных портретов, которым могли пользоваться художник и мастерская.','Произведение раскрывает рабочую сторону придворного портрета: небольшой этюд служит образцом для последующих версий.','Подготовительный портрет|Модель для мастерской|Алессандро Медичи|1534–1535 годы','Это рабочий этюд, не законченный парадный портрет. Подробная биография художника в выбранной записи отсутствует.','Рассмотри портрет как рабочий образец: музей говорит, что Понтормо и мастерская могли сверяться с ним при создании больших портретов.'],
['paolo_veronese','Паоло Веронезе','Paolo Veronese','1528–1588','cma:109507','Италия · Венеция, чинквеченто','В кливлендской записи Веронезе указан как итальянский мастер 1528–1588 годов.','Агостино Барбариго представлен военачальником: доспехи и поза связывают его с изображениями римских императоров.','Портрет превращает военную биографию в образ доблести. Стрела в руке напоминает о гибели Барбариго в битве при Лепанто 7 октября 1571 года.','Доспехи|Императорская поза|Стрела как памятный знак|Военная репрезентация','Дата «после около 1571» относится к портрету, а 1528–1588 — годы художника. Биографию модели не следует принимать за биографию автора.','Найди стрелу в руке Барбариго: она напоминает о его гибели при Лепанто. Сравни позу в доспехах с образом римского императора.'],
['andrea_del_sarto','Андреа дель Сарто','Andrea del Sarto','1486–1530','cma:117032','Италия · чинквеченто','Кливленд указывает годы жизни мастера 1486–1530. Его «Жертвоприношение Исаака» осталось незавершённым.','Рисунок переносился на доску, меловые линии усиливались краской. Затем мастер работал по всей поверхности тонкими слоями цвета, меняя композицию по ходу работы.','Незавершённость позволяет увидеть не только результат, но и процесс: перевод рисунка, уточнение контуров и изменения фигур.','Тонкие слои цвета|Видимый рисунок|Правки фигур|Сложные эмоции','Фигуры связаны музеем с античной скульптурой и Микеланджело. Незавершённость здесь документирована, а не выводится из впечатления зрителя.','Посмотри на осла справа: там особенно заметны линии рисунка. В ангеле, теле Исаака и голове Авраама музей отмечает изменения композиции.'],
['jan_gossart','Ян Госсарт','Jan Gossart','ок. 1478–1532','aic:111456','Нидерланды · северное Возрождение','Чикаго называет Госсарта первым известным нидерландским художником, изучавшим античную скульптуру в Риме.','Драпировки Марии и атлетическое тело Младенца связываются с итальянскими образцами Микеланджело и Рафаэля. При этом сохраняется северный формат диптиха.','Картина соединяет итальянский язык фигуры с нидерландской традицией переносного молитвенного образа.','Античные образцы|Атлетический Младенец|Драпировки|Формат диптиха','Существование правой створки с донатором предполагается по взгляду и жесту Младенца; это реконструкция.','Проследи взгляд и благословляющий жест Младенца вправо, за край картины: возможно, там находился молящийся заказчик.'],
['jan_van_scorel','Ян ван Скорел','Jan van Scorel','1495–1562','aic:110527','Нидерланды · северное Возрождение','Скорел был одним из первых североевропейских художников, надолго отправившихся в Италию изучать древности и новый стиль Возрождения.','Пейзаж с турниром и охотниками написан на тополевой доске — обычном для Италии материале. Северные придворные развлечения изображены во время южной поездки художника.','Пример культурного обмена: северный сюжет придворного досуга привлекал итальянских заказчиков.','Турнир|Охота|Пейзаж|Тополевая доска','Место создания выводится музеем из путешествия и материала основы. Подробная история заказа в записи не приведена.','Найди два вида аристократического досуга: турнир и охоту. Музей связывает панель с итальянской поездкой молодого художника.'],
['maerten_van_heemskerck','Мартен ван Хемскерк','Maerten van Heemskerck','1498–1574','cma:153603','Нидерланды · северное Возрождение','Хемскерк жил в Риме в 1532–1536 годах и испытал сильное влияние искусства города и античности.','Поясная сидящая фигура, напряжённые изящные руки и гротескная маска связаны музеем с римским опытом; тщательная передача фактур — с северным искусством.','Портрет сочетает античные формы с северной любовью к материальным поверхностям.','Сидящая поясная фигура|Выразительные руки|Античная маска|Точные фактуры','Парный портрет мужа не сохранился; его существование музей выводит из объединённых семейных эмблем герба.','Найди маску и висящий на ней герб, объединяющий эмблемы супругов. Сравни античную отсылку с тщательной передачей тканей.'],
['abraham_bloemaert','Абрахам Блумарт','Abraham Bloemaert','1566–1651','cma:157217','Нидерланды · маньеризм','Кливленд называет Блумарта одним из ведущих представителей маньеризма Северных Нидерландов.','Преувеличенные пропорции, закрученные позы, усиленные цвета и плотная композиция характеризуют его «Милосердие».','Традиционная группа Богоматери с Младенцем преобразована в аллегорию добродетели: женщина окружена детьми.','Удлинённые пропорции|Сложные позы|Усиленный цвет|Плотная группа','Это аллегория Милосердия, а не буквальное изображение Богоматери. Влияние религиозной композиции не означает тождества сюжетов.','Рассмотри позы женщины и детей: музей связывает их усложнённость и подчёркнутую чувственность с северным маньеризмом.'],
['giovanni_girolamo_savoldo','Джованни Джироламо Савольдо','Giovanni Girolamo Savoldo','работал 1506–1548','aic:158137','Италия · Венеция и Ломбардия, XVI век','Савольдо жил в Венеции и сохранял связи с Брешией в Ломбардии.','Трёхчетвертной формат приближает героев. Спокойное принятие смерти святым контрастирует с жестокостью нападающего.','Музей связывает мрачную поэтичность Савольдо с соединением ломбардского реализма и венецианских фактурных и атмосферных эффектов.','Приближённые фигуры|Контраст эмоций|Ломбардский реализм|Венецианская атмосфера','1506–1548 — годы активности, не даты рождения и смерти. Пётр Мученик — доминиканец XIII века, не апостол Пётр.','Сравни выражения святого и его убийцы: спокойствие и грубость противопоставлены в приближённом формате.'],
['giorgio_vasari','Джорджо Вазари','Giorgio Vasari','1511–1574','aic:110242','Италия · Флоренция, XVI век','Вазари известен как автор «Жизнеописаний наиболее знаменитых живописцев, ваятелей и зодчих». Он был также архитектором и плодовитым живописцем герцогов Медичи.','В незавершённой картине видна сетка чёрным мелом для увеличения и переноса подготовительного рисунка; она просвечивает через тонкие начальные слои краски.','Картина позволяет сравнить замысел и исполнение: рабочая сетка остаётся видимым инструментом построения композиции.','Сетка переноса|Тонкие первые слои|Незавершённость|Аллегорическое искушение','Венера и амуры здесь персонифицируют искушения Иеронима; это не самостоятельная мифологическая сцена.','Найди меловую сетку под тонкими слоями краски. Венера с амурами олицетворяет видения, искушающие Иеронима в пустыне.'],
['colijn_de_coter','Колейн де Котер','Colijn de Coter','ок. 1450 — не позднее 1540','aic:16257','Нидерланды · северное Возрождение','Чикагская запись указывает имя Колейна де Котера и приблизительные годы жизни. Других биографических подробностей выбранное описание не даёт.','Золотая надпись на красной мантии Марии цитирует антифон: «Радуйся, Царица небес, Матерь Царя ангелов». Драгоценная корона подчёркивает её достоинство.','Изображение отсылает не только к зрению, но и к слуху: слова гимна напоминают о дорогой многоголосной музыке придворной культуры Брюсселя.','Золотая надпись|Красная мантия|Корона|Связь с музыкой','Связь с придворной музыкальной культурой в описании не доказывает конкретного заказчика картины.','Найди золотые слова по краю красной мантии. Музей объясняет их как цитату из гимна, известного в многоголосном исполнении.'],
['jean_hey','Жан Эй','Jean Hey','работал около 1480–1504','aic:16327','Франция · франко-фламандская живопись','Жан Эй, также известный как Мастер Мулена, был придворным живописцем Пьера II Бурбона и Анны Французской.','Роскошная палитра и чёткость формы напоминают миниатюру; цилиндрический свод и мраморная колонна отражают интерес к античности.','Техническое исследование помогает восстановить ансамбль: рентген и инфракрасная рефлектография выявили фигуру у левого края, позднее удалённую.','Ясные формы|Дорогой ультрамарин|Античная архитектура|Фрагмент алтаря','Создание алтаря к рождению единственного ребёнка заказчиков — гипотеза. Даты около 1480–1504 не следует читать как годы жизни.','Это правая створка алтаря. Фигура слева была соскоблена и записана до 1906 года; парную створку музей связывает со встречей родителей Марии в Лондонской Национальной галерее.'],
['juan_de_flandes','Хуан де Фландес','Juan de Flandes','ок. 1460–1519','cma:148301','Нидерланды и Испания · северное Возрождение','Работа Хуана де Фландеса происходила из алтаря, заказанного Изабеллой I Кастильской для монастыря близ Бургоса.','Библейское рождение изображено в уютном нидерландском доме конца XV века. Елизавета отдыхает, Мария подносит младенца Захарии.','Священная история помещена в знакомую домашнюю обстановку: современный интерьер сближает её со зрителем.','Домашний интерьер|Бытовые детали|Библейское повествование|Испанский королевский заказ','Время действия сюжета и время создания картины различаются. Нидерландский интерьер не означает, что заказчик был нидерландским.','Захария записывает имя сына: согласно рассказу, именно в этот момент ему возвращается речь. Найди Елизавету после родов и Марию с младенцем.'],
['albert_bouts','Альберт Баутс','Albert Bouts','1451/55–1549','cma:122338','Нидерланды · северное Возрождение','Кливленд указывает приблизительные годы жизни Альберта Баутса — 1451/55–1549. Выбранное описание посвящено сюжету, а не биографии.','Мария показана обычной, но состоятельной женщиной: архангел прерывает её чтение часослова, популярной молитвенной книги позднего Средневековья.','Благовещение подано как сцена, знакомая зрителю конца XV века: домашний мир становится местом священного события.','Часослов|Современная обстановка|Состоятельная Мария|Вторжение архангела','Не путай Альберта Баутса с Дириком Баутсом и его мастерской: это разные музейные атрибуции.','Найди часослов Марии. По объяснению музея, такие книги были особенно популярны у богатой грамотной знати.']
];
if(typeof CARDS==='undefined'||!window.registerPaintingArtists)throw Error('Painting catalogue is unavailable');
const catalogue=new Map(CARDS.map(c=>[c.key,c]));const batch={};
for(const [id,name,latin,life,key,tag,bio,technique,innovation,features,caution,look] of rows){
const c=catalogue.get(key);if(!c)throw Error('Missing painting: '+key);
batch[id]={name,latin,life,tag,aliases:[name,latin],bio:[bio],technique:[technique],innovation,features:features.split('|'),caution,sources:[[c.museum+': '+c.originalTitle,c.source]],works:[{key:c.key,date:c.date,image:c.image,zoom:c.zoom,source:c.source,museum:c.museum,originalTitle:c.originalTitle,medium:c.medium,title:c.title,look}]};}
window.registerPaintingArtists(batch);
})();

;
