/* artists-batch-12.js */
(()=>{'use strict';
const a={name:'Джотто ди Бондоне',latin:'Giotto di Bondone',life:'ок. 1265–1337 (датировка NGA)',tag:'Италия · Флоренция · треченто',aliases:['Джотто ди Бондоне','Джотто','Giotto di Bondone','Giotto'],
bio:['Джотто — флорентийский мастер, чьи опыты с телесным объёмом и убедительными человеческими жестами стали важной предпосылкой искусства Возрождения. Он писал алтарные картины и фресковые циклы, а также работал как архитектор и скульптор. NGA выделяет росписи капеллы Арена в Падуе как самый известный из его фресковых ансамблей.','Дата рождения приблизительна: Национальная галерея искусства в Вашингтоне указывает около 1265 года, Уффици — 1267-й; год смерти — 1337. Здесь подробно разобрана одна работа, а не весь путь художника.'],
technique:['В вашингтонской «Мадонне с Младенцем» Джотто работает темперой на тополевой доске. Масса и объём тела важнее плоского узора: фигура ощущается телесной, хотя золотой фон сохраняет условное небесное пространство.','Следи за двумя руками Младенца: одной он держит указательный палец матери, другой тянется к розе. NGA противопоставляет этот детский жест привычному торжественному благословению. Это не отказ от священного сюжета, а его очеловечивание.','В «Маэсте Оньиссанти» Уффици отмечают сходный интерес к объёму: украшения одежд сведены к минимуму, тела моделируются светом и тенью, а частично перекрытые архитектурой фигуры создают ощущение занятого ими пространства. Репродукция этой второй работы в пакет не включена.'],
innovation:'Джотто усилил ощущение массы, телесности и человеческого присутствия в религиозной живописи. Новизну здесь можно проверить на конкретном жесте и объёме фигуры, не приписывая мастеру изобретение линейной перспективы и не называя его живопись фотографически точной.',
features:['Вес и телесный объём фигуры, а не только контур и орнамент.','Живой контакт рук матери и Младенца.','Детское движение к цветку вместо торжественного жеста благословения.','Золотой фон сохраняет значение небесного мира.','Роза и пробитый орнамент нимбов соединяют наблюдение с символикой.'],
caution:'Вашингтонская панель — центральная часть пятичастного полиптиха, а не «Маэста Оньиссанти» из Уффици. В NGA она сейчас указана под именем Джотто, но история атрибуции включает Бернардо Дадди и другие мнения. Место первоначального заказа не установлено окончательно: NGA допускает Санта-Кроче или Оньиссанти. Подтверждена лицензия CC0 конкретной репродукции на Wikimedia Commons; это не общее заявление о правах на все фотографии Джотто.',
sources:[['NGA: Madonna and Child, 1939.1.256','https://www.nga.gov/artworks/397-madonna-and-child'],['Уффици: Маэста Оньиссанти','https://www.uffizi.it/en/artworks/virgin-and-child-enthroned-surrounded-by-angels-and-saints-ognissanti-maesta'],['Wikimedia Commons: репродукция NGA 397 и CC0','https://commons.wikimedia.org/wiki/File:Giotto,_Madonna_and_Child,_c._1310-1315,_NGA_397.jpg']],
works:[{key:'nga:397',title:'Мадонна с Младенцем',originalTitle:'Madonna and Child',date:'ок. 1310–1315',museum:'Национальная галерея искусства, Вашингтон',medium:'Темпера на тополевой доске',source:'https://www.nga.gov/artworks/397-madonna-and-child',accessionNumber:'1939.1.256',image:'https://commons.wikimedia.org/wiki/Special:FilePath/Giotto%2C_Madonna_and_Child%2C_c._1310-1315%2C_NGA_397.jpg?width=960',zoom:'https://commons.wikimedia.org/wiki/Special:FilePath/Giotto%2C_Madonna_and_Child%2C_c._1310-1315%2C_NGA_397.jpg?width=2048',license:'CC0 1.0',imageSource:'https://commons.wikimedia.org/wiki/File:Giotto,_Madonna_and_Child,_c._1310-1315,_NGA_397.jpg',creditLine:'Samuel H. Kress Collection, 1939.1.256',look:'Сначала найди контакт рук: Младенец сжимает указательный палец матери и одновременно тянется к розе. Затем сравни этот естественный жест с условным золотым фоном. По объяснению NGA, белая роза означает чистоту Марии и напоминает о невинности, утраченной при грехопадении. Это центральная панель утраченного пятичастного алтаря; два сравниваемых принципа — телесность фигуры и символическое пространство — сосуществуют в одной картине.'}]
};
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists({giotto:a});
const host=document.getElementById('view');
function fixHeading(){const page=document.getElementById('artist-area');if(!page||page.querySelector('h1')?.textContent!==a.name)return;for(const h of page.querySelectorAll('h2'))if(h.textContent==='Пять работ: рассмотри и сравни')h.textContent='Одна работа: рассмотри внимательно';}
if(host){new MutationObserver(fixHeading).observe(host,{childList:true,subtree:true});fixHeading();}
})();

;
/* artists-batch-13.js */
(()=>{'use strict';
const a={name:'Чимабуэ',latin:'Cimabue (Cenni di Pepo)',life:'документирован в 1272–1302 годах',tag:'Италия · Флоренция · дученто',aliases:['Чимабуэ','Cimabue','Cenni di Pepo'],
bio:['Ченни ди Пепо, известный как Чимабуэ, — один из важнейших флорентийских живописцев XIII века. По сведениям Уффици, он работал не только в Тоскане, но также в Риме, Ассизи и Болонье. Музей указывает документированный период 1272–1302: это не годы жизни.','Его искусство выросло из византийской традиции, но не осталось неподвижным. В поздней «Маэсте Санта-Тринита» Уффици отмечают более мягкие выражения лиц и сложное пространственное построение. Музей связывает эти черты с новшествами младших современников, включая Дуччо и Джотто.'],
technique:['«Маэста Санта-Тринита» написана темперой на дереве по золотому фону. Золото здесь не заменяет обычный пейзаж: оно переносит священную сцену за пределы земного времени и пространства. Фон и нимбы украшены обработкой металлическими инструментами, а одежды — золотыми линиями.','Мария указывает правой рукой на Младенца. Этот тип восходит к византийской Одигитрии — «Указующей путь». Христос благословляет и держит свиток; торжественная фронтальность и золотой орнамент сохраняют связь с иконой.','Одновременно трон строится как сложная архитектура с арками и нишами, складки одежд становятся пластичнее, лица моделируются мягкой светотенью. Смотри не на противопоставление «плоско или объёмно», а на сосуществование условного священного пространства и попытки сделать его обитаемым.'],
innovation:'Чимабуэ соединяет византийскую торжественность с более убедительной архитектурой трона и мягкой моделировкой лиц. Важно, что эта поздняя работа показывает обмен решениями между поколениями: Уффици видят здесь отклик на натурализм Дуччо и Джотто, а не только одностороннее влияние учителя на ученика.',
features:['Золотой фон с тонким геометрическим орнаментом.','Золотые линии на одеждах Марии и Младенца.','Одигитрия: Мария рукой указывает на Христа.','Архитектурный трон и четыре фигуры под его арками.','Мягкая светотень лиц и более доброжелательные выражения.'],
caution:'Не путай «Маэсту Санта-Тринита» Чимабуэ с «Маэстой Оньиссанти» Джотто и «Мадонной Ручеллаи» Дуччо. Датировка около 1290–1300 принята Уффици, но музей подчёркивает историю споров. Первоначальная монументальная рама утрачена в XIX веке. Репродукция подключена с Wikimedia Commons и отмечена там как public domain; это не CC0 и не отдельное разрешение Уффици. Отметка авторско-правового статуса не исключает иных применимых ограничений.',
sources:[['Уффици: Маэста Санта-Тринита','https://www.uffizi.it/en/artworks/virgin-and-child-enthroned-and-prophets-santa-trinita-maesta'],['Уффици: Между человеческим и божественным — подробный разбор','https://www.uffizi.it/en/online-exhibitions/between-human-and-divine-cimabue-and-the-santa-trinita-maesta'],['Wikimedia Commons: репродукция Google Art Project и сведения о правах','https://commons.wikimedia.org/wiki/File:Cimabue_-_Maest%C3%A0_di_Santa_Trinita_-_Google_Art_Project.jpg']],
works:[{key:'uffizi:1890-8343',title:'Маэста Санта-Тринита',originalTitle:'Virgin and Child Enthroned, and Prophets (Santa Trinita Maestà)',date:'ок. 1290–1300',museum:'Галерея Уффици, Флоренция',medium:'Темпера на дереве, золотой фон; 384 × 223 см',accessionNumber:'1890 № 8343',source:'https://www.uffizi.it/en/artworks/virgin-and-child-enthroned-and-prophets-santa-trinita-maesta',image:'https://commons.wikimedia.org/wiki/Special:FilePath/Cimabue_-_Maest%C3%A0_di_Santa_Trinita_-_Google_Art_Project.jpg?width=960',zoom:'https://commons.wikimedia.org/wiki/Special:FilePath/Cimabue_-_Maest%C3%A0_di_Santa_Trinita_-_Google_Art_Project.jpg',imageSource:'https://commons.wikimedia.org/wiki/File:Cimabue_-_Maest%C3%A0_di_Santa_Trinita_-_Google_Art_Project.jpg',license:'Public domain according to Wikimedia Commons (PD-Art); not CC0',creditLine:'Cimabue; Uffizi Galleries; reproduction: Google Art Project / Wikimedia Commons',look:'Начни с правой руки Марии: она указывает на Христа. Затем проследи архитектуру трона и найди восемь ангелов, которые его приподнимают. Под троном слева направо расположены Иеремия, Авраам, Давид и Исайя со свитками: Уффици объясняют их как ветхозаветное основание новозаветного образа. Наконец сравни золотые линии одежды с мягкими тенями лиц. Картина происходила из флорентийской церкви Санта-Тринита; размещение на главном алтаре известно по Вазари. В Уффици она поступила в 1919 году.'}]
};
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists({cimabue:a});
const host=document.getElementById('view');
function fixHeading(){const page=document.getElementById('artist-area');if(!page||page.querySelector('h1')?.textContent!==a.name)return;for(const h of page.querySelectorAll('h2'))if(h.textContent==='Пять работ: рассмотри и сравни')h.textContent='Одна работа: рассмотри внимательно';}
if(host){new MutationObserver(fixHeading).observe(host,{childList:true,subtree:true});fixHeading();}
})();

;
