const refs={seraphine_louis:[['Музеи Санлиса: художница и техника','https://musees.ville-senlis.fr/seraphine-louis-dite-seraphine-de-senlis/'],['Санлис: Древо жизни и происхождение названия','https://musees.ville-senlis.fr/seraphine-louis-larbre-de-vie/']],grandma_moses:[['Bennington Museum: биография и метод','https://benningtonmuseum.org/portfolio-items/grandma-moses/']],gaetano_previati:[['Лицензия репродукции: CC BY-SA 3.0','https://creativecommons.org/licenses/by-sa/3.0/']],georges_seurat:[['Национальная галерея: художник','https://www.nationalgallery.org.uk/artists/georges-seurat']],gustave_moreau:[['Метрополитен: значение Моро','https://www.metmuseum.org/press-releases/gustave-moreau--between-epic-and-dream-1999-exhibitions']]};
