for(const [id,name,latin,life,tag,bio,technique,innovation,features,caution,keys,looks] of rows){const works=keys.map((key,i)=>{if(extra.has(key))return {...extra.get(key),look:looks[i]};const c=catalogue.get(key);if(!c)throw Error('Missing painting '+key);return {key:c.key,title:c.title,originalTitle:c.originalTitle,date:c.date,museum:c.museum,medium:c.medium,source:c.source,image:c.image,zoom:c.zoom||c.image,look:looks[i]};});const sources=[...works.map(w=>[w.museum+': '+w.originalTitle,w.source]),...works.filter(w=>w.imageSource).map(w=>['Репродукция и сведения о правах',w.imageSource]),...(refs[id]||[])];batch[id]={name,latin,life,tag,aliases:[name,latin],bio:[bio],technique:[technique],innovation,features:features.split('|'),caution,sources,works,editorialStatus:works.length?'illustrated':'text_only_image_rights_pending'};}
