/* artists-batch-21.js */
(()=>{'use strict';
const rows=[
['ernst_ludwig_kirchner','Эрнст Людвиг Кирхнер','Ernst Ludwig Kirchner','1880–1938','Германия · экспрессионизм · Die Brücke','В 1905 Кирхнер вместе с Блейлем, Хеккелем и Шмидт-Ротлуфом основал Die Brücke. Группа стремилась к непосредственному личному выражению.','В Борцах в цирке свободные мазки размывают контуры движущихся тел на ярком ковре. Напряжение возникает из сочетания сцепленной позы и цвета.','Изменённая форма служит эмоциональному содержанию, а не только оптической записи движения.','Свободный мазок|Яркий ковёр|Сцепленные тела|Движение контура|Напряжённая сцена','Одна картина 1909 не исчерпывает творчество Кирхнера. Не называем всякую яркую живопись экспрессионизмом: важно, как цвет и форма выражают состояние.',['cma:142792'],['Проследи границы тел: где мазок сохраняет форму, а где передаёт смазанное движение? Музей предлагает представить шум цирковой публики.']],
['franz_marc','Франц Марк','Franz Marc','1880–1916','Германия · экспрессионизм · Синий всадник','Марк стремился представить природу через восприятие животных. Зачарованная мельница написана после поездки в Мерано.','Дома и мельница слева противопоставлены лирическому миру деревьев и животных справа. Сильный цвет и изменённая форма связывают части.','По музейному разбору картина выражает пережитую художником гармонию человека и природы, не магическое происшествие в буквальном смысле.','Сильный цвет|Преобразованная форма|Животные и деревья|Дома и мельница|Гармония двух миров','Название метафорично. Не всякая работа Марка абстрактна: здесь важны узнаваемые мотивы и их взаимодействие.',['aic:9021'],['Сравни левую архитектурную часть с правой природной. Какими цветовыми и формальными связями они объединены?']],
['emil_nolde','Эмиль Нольде','Emil Nolde','1867–1956','Германия · экспрессионизм','Живописец, акварелист и график, Нольде вступил в Die Brücke в 1906. MoMA связывает усиление религиозных тем с пережитым им духовным переломом.','Разбор основан на Пророке 1912 — ксилографии, не картине маслом. Грубые выемки, ломаные линии и фактура дерева усиливают воздействие лица.','Материал и техника становятся частью эмоционального содержания: след дерева не скрыт, а активно работает.','Резкий чёрно-белый контраст|Ломаная линия|Полые глаза|Фактура доски|Эмоциональная сосредоточенность','Пока без изображения: MoMA указывает © Nolde Stiftung Seebüll и условия запроса разрешения. Не переносим признаки ксилографии автоматически на его акварели и картины.',[],[]],
['pablo_picasso','Пабло Пикассо','Pablo Picasso','1881–1973','Испания и Франция · кубизм и другие периоды','С 1908 Пикассо и Брак развивали кубизм в тесном диалоге. Разбор портрета Канвейлера осени 1910 относится именно к раннему кубизму.','После многочисленных сеансов фигура превращена в сеть полупрозрачных граней, показанных с нескольких точек зрения. Волосы, галстук и цепочка часов помогают узнать сидящего человека.','Предмет не исчезает, а заново собирается на плоскости: зритель сопоставляет фрагменты и опорные детали.','Дробные грани|Несколько точек зрения|Сдержанная гамма|Слияние фигуры и среды|Узнаваемые якоря','Пока только текст и музейная ссылка: на странице стоит © Estate of Pablo Picasso / ARS. Не используем Старого гитариста как пример кубизма: это Голубой период.',[],[]],
['georges_braque','Жорж Брак','Georges Braque','1882–1963','Франция · кубизм','Маленькая гавань в Нормандии весны 1909 связана с началом совместных исследований Брака и Пикассо. Музей считает её важным ранним кубистическим пейзажем.','Строгая геометрия, сжатая глубина, меняющаяся перспектива и неброская палитра преобразуют берег и две лодки.','Пространство перестаёт быть окном с единой фиксированной точки. Вещи остаются узнаваемыми, но их отношения перестроены.','Сжатое пространство|Геометрические формы|Сдержанные цвета|Сдвиг перспективы|Две лодки','Пока без встроенной репродукции: разрешение не подтверждено. Кубизм не равен любой геометризации и не обязательно полностью беспредметен.',[],[]],
['juan_gris','Хуан Грис','Juan Gris','1887–1927','Испания и Франция · кубизм','Грис приехал в Париж в 1906, познакомился с Пикассо и Браком и участвовал в развитии кубизма. Портрет Пикассо выставлен в Салоне независимых 1912.','Голова, шея и торс разложены на плоскости, но подчинены системе диагоналей. Холодные голубые, коричневые и серые тона создают кристаллическую структуру.','От аналитического кубизма Грис идёт к более систематической геометрической организации, сохраняя конкретную модель.','Дробные плоскости|Регулирующие диагонали|Холодная гамма|Палитра в руке|Надпись-посвящение','Автор — Грис, изображённый — Пикассо. Это живопись января–февраля 1912, не посмертно напечатанный офорт с похожим названием.',['new:gris'],['Найди палитру и посвящение Hommage à Pablo Picasso. Сравни расчленение лица с упорядоченной системой диагоналей. Репродукция: Google Art Project / Wikimedia Commons.']],
['piet_mondrian','Пит Мондриан','Piet Mondrian','1872–1944','Нидерланды · De Stijl · неопластицизм','Мондриан пришёл к беспредметной сетке через пейзаж и кубизм. После начала абстрактных опытов он продолжал возвращаться к более ранним природным мотивам.','Вертикали и горизонтали, прямоугольные зоны, основные цвета и нейтральные тона организуют равновесие. Поворот холста ромбом меняет отношения изображения с краем и стеной.','По музейным текстам универсальный визуальный язык связывался с надеждой на гармоничное общество после Первой мировой войны.','Вертикаль и горизонталь|Основные цвета|Нейтральные зоны|Асимметричное равновесие|Активная граница холста','Ромбовидный холст не означает диагональных линий внутри композиции. Творчество не делится на простые непересекающиеся стадии: ферма написана около 1916, уже после знакомства с кубизмом.',['aic:144467','aic:109819','cma:143278'],['Сравни повторяющиеся деревья и плоскости отражения. Возврат к пейзажу музей предположительно связывает с предпочтениями заказчиков.','Найди линию, уходящую к наклонному краю: она предполагает продолжение за пределами холста.','Сопоставь площади цветных и нейтральных прямоугольников: равновесие не равно зеркальной симметрии.']],
['theo_van_doesburg','Тео ван Дусбург','Theo van Doesburg','1883–1931','Нидерланды · De Stijl · элементаризм','В 1917 ван Дусбург основал журнал De Stijl, объединив художников, архитекторов и дизайнеров. Его целью был синтез искусства и жизни.','В ранней Композиции I 1916 ещё угадывается натюрморт, включая лимон. Контркомпозиция X 1924 позволяет сравнить иной этап геометрической организации.','Абстрактная форма входила в программу переустройства среды и общества, а не была только декоративным узором.','Геометрические зоны|Наклонные отношения|Ограниченный цвет|Новая организация плоскости|Связь искусства и среды','Репродукция X всего 661 × 654 пикселя. Не подменяем её файлом early state и не переносим натюрмортное описание Композиции I на другую картину.',['new:doesburg'],['Сопоставь наклонные цветовые зоны с краями квадрата. Для сравнения с ранним натюрмортом используй отдельную музейную ссылку. Репродукция отмечена Commons как PD-Art; детализация ограничена.']],
['bart_van_der_leck','Барт ван дер Лек','Bart van der Leck','1876–1958','Нидерланды · De Stijl и фигуративная абстракция','Ван дер Лек начинал с витражей. В 1917 стал одним из основателей De Stijl, но затем отошёл от стремления коллег к абсолютной беспредметности.','В Буре 1916 рыбацкие жёны смотрят в море. Фигуры сведены к изолированным блокам, цвета — к основным и нейтральным.','Сильное упрощение не отменяет сюжета: жёлтый пляж и синее море сохраняют связь с видимой действительностью.','Изолированные формы|Основные цвета|Фигуры-блоки|Узнаваемый сюжет|Влияние витража','Пока только текст: право на повторную публикацию изображения не подтверждено. Не считаем всех участников De Stijl сторонниками полного отказа от предметного мира.',[],[]],
['vasily_kandinsky','Василий Кандинский','Vasily Kandinsky','1866–1944','Россия Германия Франция · Синий всадник и абстракция','В мюнхенском круге Синего всадника Кандинский связывал формы и цвета с духовным, эмоциональным и мнемоническим воздействием. Музей отмечает влияние народного и средневекового искусства.','В Картине с тройкой 1911 ещё есть узнаваемый экипаж и расписанная автором рама. Работа 1913 с зелёным центром позволяет сравнить степень предметной определённости.','Самостоятельные отношения цвета и формы могут выражать состояние без обязательного буквального рассказа. Это не отменяет узнаваемых мотивов в ранних работах.','Выразительный мазок|Активный цвет|Народный источник|Авторская рама|Ослабление предметной определённости','Не называем каждую работу Кандинского беспредметной. В записи Зелёного центра нет подробного музейного толкования: вопросы к ней являются редакционными, не цитатой художника.',['aic:8983','aic:8987'],['Найди экипаж с тремя лошадьми и рассмотри авторскую раму: оба мотива связывают работу с народными источниками.','Как зелёный участок связан с окружающими цветовыми и линейными формами? Попробуй описать композицию, не выдумывая обязательный сюжет.']],
['amedeo_modigliani','Амедео Модильяни','Amedeo Modigliani','1884–1920','Италия и Париж · самостоятельная портретная манера','После итальянского обучения Модильяни поселился в Париже в 1906. Жак Липшиц заказал парный портрет к своей свадьбе с поэтом Бертой Китроссер.','В Мадам Помпадур удлинённые формы сочетаются с сеткой фона и перекликающимися изгибами шляпы, плеч и лица.','Стилизация сохраняет портретную конкретность и может создавать иронию, а не только меланхолию.','Удлинённая форма|Ритм изгибов|Формальная структура|Портретный мотив|Сдержанное выражение','Мадам Помпадур — название 1915, не портрет исторической фаворитки XVIII века. Отождествление модели с Беатрис Гастингс не доказано. Не объясняем стиль только богемной легендой.',['aic:27281','aic:27987'],['Сопоставь кривые шляпы и плеч с сеткой фона. Музей видит здесь скорее ироническую дистанцию, чем обязательную печаль.','Парный портрет заказан самими моделями. По воспоминанию Липшица работа была быстро начата, а продолжение помогало финансово поддержать художника.']]
];
if(typeof CARDS==='undefined'||typeof window.registerPaintingArtists!=='function')throw Error('Painting catalogue unavailable');
const C='https://commons.wikimedia.org/wiki/';
const newRows=[
['gris','Портрет Пабло Пикассо','январь–февраль 1912','Художественный институт Чикаго','https://www.artic.edu/artworks/8624/portrait-of-pablo-picasso','Juan Gris - Portrait of Pablo Picasso - Google Art Project.jpg'],
['doesburg','Контркомпозиция X','1924','Музей Крёллер-Мюллер, Оттерло','https://tijdlijn.krollermuller.nl/en/timeline/historical-continuity','Theo van Doesburg Counter-composition X 1924.jpg']
];
const extra=new Map(newRows.map(([id,title,date,museum,source,file])=>['new:'+id,{key:'guide21:'+id,title,originalTitle:title,date,museum,medium:'Масло на холсте',source,image:C+'Special:FilePath/'+encodeURIComponent(file)+'?width=650',zoom:C+'Special:FilePath/'+encodeURIComponent(file)+'?width=2048',imageSource:C+'File:'+encodeURIComponent(file),license:'Public domain / PD-Art according to cited image sources'}]));
const refs={ernst_ludwig_kirchner:[['MoMA: Кирхнер и Die Brücke','https://www.moma.org/artists/3115-ernst-ludwig-kirchner']],emil_nolde:[['MoMA: биография','https://www.moma.org/artists/4327-emil-nolde'],['MoMA: Пророк, техника и правообладатель','https://www.moma.org/collection/works/62151']],pablo_picasso:[['Чикаго: Канвейлер, осень 1910, описание и copyright','https://www.artic.edu/artworks/111060/daniel-henry-kahnweiler'],['Чикаго: разные периоды Пикассо','https://www.artic.edu/articles/1105/made-for-the-present-the-many-styles-of-pablo-picasso']],georges_braque:[['Чикаго: Маленькая гавань в Нормандии, 1909','https://www.artic.edu/artworks/109330/little-harbor-in-normandy']],theo_van_doesburg:[['Крёллер-Мюллер: Композиция I, 1916, не показанное произведение','https://www.krollermuller.nl/en/collection/theo-van-doesburg-composition-i-still-life-km-106-123']],bart_van_der_leck:[['Крёллер-Мюллер: Буря, 1916','https://krollermuller.nl/en/bart-van-der-leck-the-tempest-1']],vasily_kandinsky:[['Чикаго: Картина с зелёным центром, данные без толкования','https://www.artic.edu/artworks/8987/painting-with-green-center']]};
const catalogue=new Map(CARDS.map(c=>[c.key,c])),batch={};
for(const [id,name,latin,life,tag,bio,technique,innovation,features,caution,keys,looks] of rows){const works=keys.map((key,i)=>{if(extra.has(key))return {...extra.get(key),look:looks[i]};const c=catalogue.get(key);if(!c)throw Error('Missing painting '+key);return {key:c.key,title:key==='aic:8987'?'Картина с зелёным центром':c.title,originalTitle:c.originalTitle,date:c.date,museum:c.museum,medium:c.medium,source:c.source,image:c.image,zoom:c.zoom||c.image,look:looks[i]};});const sources=[...works.map(w=>[w.museum+': '+w.originalTitle,w.source]),...works.filter(w=>w.imageSource).map(w=>['Репродукция и сведения о правах',w.imageSource]),...(refs[id]||[])];batch[id]={name,latin,life,tag,aliases:[name,latin],bio:[bio],technique:[technique],innovation,features:features.split('|'),caution,sources,works,editorialStatus:works.length?'illustrated':'text_only_permission_pending'};}
batch.vasily_kandinsky.aliases.push('Wassily Kandinsky');
window.registerPaintingArtists(batch);
const byName=new Map(Object.values(batch).map(a=>[a.name,a])),host=document.getElementById('view');
function fixHeading(){const page=document.getElementById('artist-area'),a=byName.get(page?.querySelector('h1')?.textContent);if(!a)return;for(const h of page.querySelectorAll('h2'))if(h.textContent==='Пять работ: рассмотри и сравни')h.textContent=a.works.length===3?'Три работы: рассмотри и сравни':a.works.length===2?'Две работы: рассмотри и сравни':a.works.length?'Одна работа: рассмотри внимательно':'Репродукция пока не подключена';}
if(host){new MutationObserver(fixHeading).observe(host,{childList:true,subtree:true});fixHeading();}
})();

