const refs={yi_nyeong:[['AKS: Река Йесон, описание утраченной картины','https://encykorea.aks.ac.kr/Article/E0037958'],['AKS: Южные ворота Чхонсу, свидетельства и реконструкция','https://encykorea.aks.ac.kr/Article/E0055931']],yi_jehyeon:[['AKS: биография учёного и литератора','https://encykorea.aks.ac.kr/Article/E0045877'],['AKS: художник, модель, заказчик и надписи','https://encykorea.aks.ac.kr/Article/E0046803'],['Национальный музей Кореи: портрет и Presumably Chen Jianru','https://www.museum.go.kr/ENG/contents/E0403000000.do?searchId=represent&schM=view&relicId=1260'],['Korea Journal 2024: исследование портрета и вопрос копии','https://accesson.kr/kj/assets/pdf/43294/journal-64-2-17.pdf']],king_gongmin:[['Исследование 2015: работы, предположительно связанные с Конмином','https://www.earticle.net/Article/A251874'],['Музейный памятник: предположительно каллиграфия Конмина, не живопись','https://www.museum.go.kr/ENG/contents/E0403000000.do?schM=relic_represent_view&relicId=497']],an_gyeon:[['Национальный музей Кореи: заказ Анпхёна и сохранившийся шедевр','https://www.museum.go.kr/ENG/contents/E0401000000.do?schM=view&relicRecommendId=519671'],['Korea.net: оригинал в Тэнри и цифровая версия','https://www.korea.net/NewsFocus/Culture/view?articleId=132671'],['World History Encyclopedia: изображение помечено Public Domain','https://www.worldhistory.org/image/13344/mongyudowondo-dream-journey-to-the-peach-blossom-l/']],jeong_seon:[['Национальный музей Кореи: дар и история произведения','https://www.museum.go.kr/MUSEUM/contents/M0701040000.do?schM=view&catCustomType=post&catId=93&arcId=17706&cp=114&sv='],['Страница репродукции: PD-Art и прежнее собрание','https://en.wikipedia.org/wiki/File:Inwangjesaekdo.jpg']],kim_hongdo:[['Музей: альбом и годы жизни','https://www.museum.go.kr/ENG/contents/E0202010000.do?schM=view&menuId=current&exhiSpThemId=542310&listType=gallery']]};
