for(const [id,name,latin,life,tag,bio,technique,innovation,features,caution,keys,looks,status] of rows){const selected=keys.map((key,i)=>{if(!works.has(key))throw Error('Missing work '+key);return {...works.get(key),look:looks[i]};});const sources=[...selected.map(w=>[w.museum+': '+w.originalTitle,w.source]),...selected.map(w=>['Репродукция и сведения о правах',w.imageSource]),...(refs[id]||[])];batch[id]={name,latin,life,tag,aliases:[name,latin],bio:[bio],technique:[technique],innovation,features:features.split('|'),caution,sources,works:selected,editorialStatus:status==='illustrated'?'illustrated':status==='context'?'historical_context_not_verified_painter':'text_only_historical_attribution',personRole:status==='context'?'scholar_and_portrait_subject':'artist_or_historical_attribution'};}
