for(const [id,name,latin,life,tag,bio,technique,innovation,features,caution,key,look,source,status] of rows){let works=[];if(key){if(extra.has(key))works=[{...extra.get(key),look}];else{const c=catalogue.get(key);if(!c)throw Error('Missing painting '+key);works=[{key:c.key,title:titles[key]||c.title,originalTitle:c.originalTitle,date:c.date,museum:c.museum,medium:c.medium,source:c.source,image:c.image,zoom:c.zoom||c.image,look}];}}const sources=[['Основной музейный источник',source],...works.filter(w=>w.imageSource).map(w=>['Репродукция и сведения о правах',w.imageSource])];batch[id]={name,latin,life,tag,aliases:[name,latin],bio:[bio],technique:[technique],innovation,features:features.split('|'),caution,sources,works,pendingWorks:[],editorialStatus:status==='illustrated'?'illustrated':status==='historical'?'text_only_attribution_group':status==='attribution'?'text_only_attribution_review':status==='permission'?'text_only_permission_pending':'text_only_image_verification_pending'};}
