/* artists-batch-36.js */
(()=>{'use strict';
const root='https://www.nationalgallery.org.uk/',commons='https://commons.wikimedia.org/wiki/',B={};
function work(id,title,originalTitle,date,medium,file,look){return {key:'ng:'+id,title,originalTitle,date,medium,museum:'Национальная галерея, Лондон',accessionNumber:id,source:root+'paintings/'+({'NG583':'paolo-uccello-the-battle-of-san-romano','NG1417':'andrea-mantegna-the-agony-in-the-garden','NG3937':'domenico-ghirlandaio-the-virgin-and-child'}[id]),image:commons+'Special:FilePath/'+encodeURIComponent(file)+'?width=800',zoom:commons+'Special:FilePath/'+encodeURIComponent(file)+'?width=1600',imageSource:commons+'File:'+file.replaceAll(' ','_'),license:'PD-Art: фотографическая репродукция двумерного произведения в общественном достоянии по Commons; условия повторного использования могут различаться по странам',imageVisuallyReviewed:false,look};}
B.paolo_uccello={name:'Паоло Уччелло',latin:'Paolo Uccello',life:'ок. 1397–1475',tag:'Италия · Флоренция, кватроченто',aliases:['Паоло Уччелло','Уччелло','Paolo Uccello','Uccello','Паоло ди Доно'],bio:['Уччелло сочетал декоративность интернациональной готики с интересом к линейной перспективе. Его искусство показывает, что готическая изысканность и ренессансные исследования пространства могли сосуществовать.','Три панели «Битвы при Сан-Романо» прославляют победу флорентийцев в 1432 году. Сейчас они находятся в Лондоне, Париже и Флоренции. Лондонская панель показывает полководца Никколо да Толентино на белом коне.'],technique:['В лондонской панели сломанные копья образуют на земле подобие перспективной сетки, а обломки доспехов показаны под разными углами. Это исследование пространства, но не безупречная единая система: музей обращает внимание и на противоречивые ракурсы.','Яичная темпера с некоторым применением масла по тополю; в доспехах и тканях использованы настоящее серебро и золото. Серебро потемнело, а часть красок и моделировки изменилась или утрачена. Нынешняя плоскостность не целиком принадлежит первоначальному замыслу.'],innovation:'Перспектива становится самостоятельной художественной задачей и способом упорядочить сложное событие. Вместо хаоса боя возникает почти придворное зрелище: геометрическая организация соединена с прославлением флорентийской победы.',features:['Перспективная сетка: сломанные копья направляют взгляд в глубину.','Ракурсы: части доспехов показаны под разными углами.','Декоративный ритм: кони, ткани и копья складываются в узор.','Драгоценные материалы: золото и серебро первоначально усиливали блеск.','Сочетание традиций: готическая изысканность рядом с исследованием пространства.'],caution:'1432 — дата битвы, не написания. Для NG583 принята текущая музейная датировка: предположительно около 1438–1440; на Commons встречается старая датировка 1450-ми. Порядок трёх панелей не установлен с уверенностью. Верх картины переделан. Разбор посвящён одной панели, а не всему творчеству. Изображение проверено по описанию и инвентарному номеру, но не просмотрено визуально.',sources:[['Национальная галерея: Паоло Уччелло',root+'artists/paolo-uccello'],['Национальная галерея: Битва при Сан-Романо, NG583',root+'paintings/paolo-uccello-the-battle-of-san-romano'],['Commons: репродукция лондонской панели',commons+'File:San_Romano_Battle_(Paolo_Uccello,_London)_01.jpg']],works:[work('NG583','Битва при Сан-Романо: Никколо да Толентино','Niccolò Mauruzi da Tolentino at the Battle of San Romano','предположительно около 1438–1440','Яичная темпера с некоторым применением масла по тополю; 182 × 320 см','San Romano Battle (Paolo Uccello, London) 01.jpg','Найди полководца на белом коне в красно-золотой шапке. Затем проследи сетку сломанных копий на переднем плане. Музей предупреждает: нынешние тёмные доспехи первоначально блестели серебром.')],editorialStatus:'museum_sources_commons_image_browser_check_pending'};
B.andrea_mantegna={name:'Андреа Мантенья',latin:'Andrea Mantegna',life:'ок. 1431–1506',tag:'Италия · Падуя и Мантуя, кватроченто',aliases:['Андреа Мантенья','Мантенья','Andrea Mantegna','Mantegna'],bio:['Мантенья родился близ Падуи и работал у Франческо Скварчоне. Позднее он служил при дворе Гонзага в Мантуе. Лондонское «Моление о чаше» относится к раннему падуанскому периоду.','Его интерес к античному искусству заметен даже в евангельском сюжете: Национальная галерея сопоставляет спящих апостолов со статуями римских императоров, а складки одежды — с тогами.'],technique:['«Моление о чаше» написано яичной темперой по дереву. Тщательное письмо позволяет различать мелкие детали каменного города и пейзажа. Фигуры имеют отчётливую, почти скульптурную форму.','Один апостол лежит ногами к зрителю: сокращение тела в ракурсе делает глубину ощутимой. Каменистое пространство связывает молящегося Христа, уснувших учеников и отряд, приближающийся для ареста.'],innovation:'Мантенья соединяет античную пластическую ясность с ракурсом и повествованием. Дорога от города к Христу превращает пейзаж в рассказ о приближении ареста: устройство пространства помогает передать течение времени и напряжение.',features:['Скульптурные фигуры: тела и складки выглядят словно высеченными.','Сильный ракурс: направленное к зрителю тело сокращается в глубину.','Античные связи: фигуры напоминают римскую скульптуру.','Каменный ландшафт: скалы и архитектура отчётливо очерчены.','Пейзаж как рассказ: путь отряда связывает части сцены.'],caution:'Мантенья жил и после 1500 года: кватроченто здесь описывает традицию и выбранную раннюю работу, а не календарные границы всего творчества. Лондонская картина NG1417 — не композиция Джованни Беллини и не пределла алтаря Сан-Дзено. Приведены музейные размеры 62,9 × 80 см; Commons округляет высоту до 63 см. Визуальный просмотр файла и загрузка в браузере ещё не проверены.',sources:[['Национальная галерея: Андреа Мантенья',root+'artists/andrea-mantegna'],['Национальная галерея: Моление о чаше, NG1417',root+'paintings/andrea-mantegna-the-agony-in-the-garden'],['Commons: репродукция NG1417',commons+'File:Mantegna,_Andrea_-_Agony_in_the_Garden_-_National_Gallery,_London.jpg']],works:[work('NG1417','Моление о чаше','The Agony in the Garden','около 1455–1456','Яичная темпера по дереву; 62,9 × 80 см','Mantegna, Andrea - Agony in the Garden - National Gallery, London.jpg','Сравни сокращённые в ракурсе тела уснувших апостолов с каменными уступами. Найди дорогу, по которой приближается отряд: она связывает далёкий город с предстоящим арестом Христа.')],editorialStatus:'museum_sources_commons_image_browser_check_pending'};
B.domenico_ghirlandaio={name:'Доменико Гирландайо',latin:'Domenico Ghirlandaio',life:'1449–1494',tag:'Италия · Флоренция, кватроченто',aliases:['Доменико Гирландайо','Гирландайо','Domenico Ghirlandaio','Ghirlandaio','Доменико Бигорди'],bio:['Настоящее имя Гирландайо — Доменико Бигорди. Он работал во Флоренции, Риме и Сан-Джиминьяно. Национальная галерея осторожно сообщает, что его учителем считался Алессо Бальдовинетти.','На странице рассмотрены камерная религиозная живопись и портрет: «Мадонна с Младенцем» и «Портрет молодого человека в красном», обе работы предположительно около 1480–1490 годов. Это не обзор его больших фресковых циклов.'],technique:['В «Мадонне с Младенцем» объёмные, чётко очерченные лица и широкие складки красного платья создают ощущение присутствия фигур. Инфракрасное исследование выявило подготовительный рисунок углеродным чёрным пигментом.','Яркая полосатая ткань подчёркивает передний план, а размытые очертания пейзажа отодвигают даль. В портрете NG2489 тонкие плотные штрихи передают гладкость кожи; трёхчетвертной поворот и пейзаж музей связывает с нидерландской традицией.'],innovation:'Живопись соединяет убедительную телесность с пространством, открытым за фигурами. Домашний молитвенный образ действует и как окно в пейзаж, а трёхчетвертной портрет делает присутствие модели более непосредственным, чем традиционный профиль.',features:['Подготовительный рисунок: композиция тщательно выстроена до нанесения красок.','Весомые фигуры: тело и складки имеют ясный объём.','Контраст планов: яркая ткань впереди и мягкая пейзажная даль.','Тонкое письмо лица: небольшие штрихи создают гладкость кожи.','Северные связи: поворот портретной фигуры и пейзаж напоминают нидерландские решения.'],caution:'«Мадонну с Младенцем» NG3937 прежде относили к мастерской, но после расчистки музей признал собственноручной работой Гирландайо. Это не основание приписывать ему все картины мастерской: «Портрет девушки» и «Костанца Каэтани» имеют другие оговорки. Арочный верх NG3937 восстановлен позднее; азурит плаща изменился, и первоначально он был синее. Файл на Commons — только 508 × 800 пикселей: увеличение не добавит деталей. Визуальный просмотр и загрузка в браузере ещё не проверены.',sources:[['Национальная галерея: Доменико Гирландайо',root+'artists/domenico-ghirlandaio'],['Национальная галерея: Мадонна с Младенцем, NG3937',root+'paintings/domenico-ghirlandaio-the-virgin-and-child'],['Национальная галерея: Портрет молодого человека в красном, NG2489',root+'paintings/domenico-ghirlandaio-portrait-of-a-young-man-in-red'],['Commons: репродукция NG3937',commons+'File:Domenico_Ghirlandaio_(1449-1494)_-_The_Virgin_and_Child_-_NG3937_-_National_Gallery.jpg']],works:[work('NG3937','Мадонна с Младенцем','The Virgin and Child','предположительно около 1480–1490','Яичная темпера по тополю; 88,9 × 57,8 см','Domenico Ghirlandaio (1449-1494) - The Virgin and Child - NG3937 - National Gallery.jpg','Найди поднятый указательный палец Младенца: музей связывает жест с его будущей проповедью. Сравни резкие складки и полосатую ткань переднего плана с мягкой далью. Зеленовато-синий плащ изменил цвет со временем.')],editorialStatus:'museum_sources_commons_image_browser_check_pending'};
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

