/* artists-batch-38.js */
(()=>{'use strict';
const N='https://www.nationalgallery.org.uk/',C='https://commons.wikimedia.org/wiki/',B={};
function add(id,name,latin,life,aliases,bio,technique,innovation,features,caution,slug,acc,title,originalTitle,date,medium,file,look,artistSlug){const source=N+'paintings/'+slug,imageSource=file?C+'File:'+file.replaceAll(' ','_'):null;B[id]={name,latin,life,tag:'Италия · кватроченто',aliases:[name,latin,...aliases],bio,technique,innovation,features,caution,sources:[['Национальная галерея: художник',N+'artists/'+artistSlug],['Национальная галерея: '+title,source],...(imageSource?[['Commons: репродукция и сведения о правах',imageSource]]:[])],works:file?[{key:'ng:'+acc,title,originalTitle,date,medium,museum:'Национальная галерея, Лондон',accessionNumber:acc,source,image:C+'Special:FilePath/'+encodeURIComponent(file)+'?width=800',zoom:C+'Special:FilePath/'+encodeURIComponent(file)+'?width=1600',imageSource,license:'PD-Art по странице Commons; условия использования фотографических репродукций могут различаться по странам',imageVisuallyReviewed:false,look}]:[],editorialStatus:file?'museum_sources_commons_image_browser_check_pending':'text_only_image_rights_pending'};}
add('filippino_lippi','Филиппино Липпи','Filippino Lippi','ок. 1457–1504',['Филиппино','Filippino'],
['Филиппино — сын Фра Филиппо Липпи и Лукреции Бути, вероятно родившийся в Прато около 1457 года. После смерти отца в 1469 году он вскоре оказался в мастерской Боттичелли; одна из лондонских композиций «Поклонения волхвов» имеет совместную атрибуцию этих двух мастеров.','Он создавал большие фресковые циклы во Флоренции и Риме и алтари для заказчиков из разных итальянских городов. Национальная галерея рассматривает его как связующее звено между достижениями XV века и искусством Высокого Возрождения.'],
['В алтаре около 1485 года Богоматерь и два святых образуют треугольник на фоне пейзажа. Иероним показан дважды: на переднем плане и вдали в пещере. Повтор фигуры объединяет молитвенный образ с рассказом о святом.','Масло и яичная темпера по дереву, вероятно тополю. Детали природы вступают в смысловую связь с главной сценой: птица за Марией кормит птенцов, повторяя мотив кормления Младенца.'],
'Тип «святого собеседования» объединяет святых разных времён в общем пространстве. Филиппино связывает устойчивую группу с живым пейзажем, повторяющимися мотивами и небольшими повествовательными эпизодами.',
['Треугольная группа: Мария и коленопреклонённые святые организуют композицию.','Общий пейзаж: святые объединены пространством, а не раздельными ячейками.','Повтор героя: Иероним появляется и вблизи, и вдалеке.','Природная параллель: птица кормит птенцов рядом с кормящей Богоматерью.','Алтарный ансамбль: основная сцена связана с нижней горизонтальной панелью.'],
'Не путай Филиппино с его отцом Фра Филиппо Липпи. NG293 происходит из капеллы Ручеллаи в Сан-Панкрацио во Флоренции. Нынешняя сложная рама — воспроизведение XIX века, а не бесспорно первоначальная. Указание на бегство в Египет в дальнем плане музей подаёт как возможность. Размер файла Commons 697 × 800 пикселей: увеличение не добавит деталей. Визуальный просмотр и загрузка в браузере не проверены.',
'filippino-lippi-the-virgin-and-child-with-saints-jerome-and-dominic','NG293','Мадонна с Младенцем, святым Иеронимом и святым Домиником','The Virgin and Child with Saints Jerome and Dominic','около 1485','Масло и яичная темпера по дереву, вероятно тополю; 203,2 × 186,1 см','Filippino Lippi (c.1457-1504) - The Virgin and Child with Saints Jerome and Dominic - NG293 - National Gallery.jpg','Найди треугольник, образованный Марией и святыми. Затем отыщи второго Иеронима в пещере и птицу, кормящую птенцов: пейзаж содержит продолжение рассказа и параллель главной сцене.','filippino-lippi');
add('pietro_perugino','Пьетро Перуджино','Pietro Perugino','жил в 1469; умер в 1523',['Перуджино','Perugino','Пьетро Ваннуччи'],
['Пьетро Ваннуччи родился в Читта-делла-Пьеве; имя Перуджино связано с Перуджей, где он работал. Он руководил несколькими мастерскими и пользовался международным успехом. Около 1500 года с ним в Перудже работал Рафаэль.','С конца XV века его отличает «сладостная», мягкая манера. «Архангел Рафаил с Товией» входит в нижний ярус алтаря для Чертозы близ Павии, заказанного миланским герцогом Лодовико Сфорца.'],
['Мягкие переходы цвета и тонкие полупрозрачные слои масла придают коже нежность, а краскам глубину. Светлый грунт участвует в моделировке тела. Мастерство передачи материала видно даже в серебристой чешуе рыбы.','Позы Рафаила и Товии подготовлены рисунком с натуры с участием помощников мастерской. Нежный обмен взглядами и соприкосновение пальцев выражают заботу и защиту. Просторный пейзаж продолжается на соседних панелях.'],
'Перуджино соединяет убедительные фактуры с ясной и спокойной организацией религиозного образа. Масляные лессировки и согласованные позы превращают движение в сдержанный ритм; в этой работе главное — не модный костюм, а покровительство архангела мальчику.',
['Мягкая моделировка: тона плавно переходят друг в друга.','Полупрозрачные слои: лессировки изменяют цвет нижележащей краски.','Нежный жест: соприкосновение пальцев передаёт заботу.','Открытый пейзаж: даль объединяет части алтаря.','Точная деталь: блеск чешуи контрастирует с мягкой кожей.'],
'1469 — год, когда художник уже жил, не дата рождения. Учёбу у Пьеро делла Франчески музей считает предположением. NG288.3 — отдельная панель, не весь алтарь; нижний край обрезан в XVIII веке, поэтому от собаки видна только голова. Товия — сын Товита; архангел Рафаил — персонаж сюжета, не художник Рафаэль. Карьера продолжалась после 1500 года. Визуальный просмотр и загрузка в браузере не проверены.',
'pietro-perugino-the-archangel-raphael-with-tobias','NG288.3','Архангел Рафаил с Товией','The Archangel Raphael with Tobias','около 1496–1500','Масло по дереву, вероятно тополю; 113,3 × 56,5 см','Pietro Perugino cat54c.jpg','Сравни нежное прикосновение пальцев с внимательными взглядами героев. Найди рыбу в руке Товии, коробочку архангела и голову собаки у нижнего края: обрезка панели изменила первоначальную композицию.','pietro-perugino');
add('luca_signorelli','Лука Синьорелли','Luca Signorelli','ок. 1440/1450–1523',['Синьорелли','Signorelli'],
['Синьорелли происходил из Кортоны и работал с 1470-х годов до смерти в 1523 году. Он получал заказы в разных городах Центральной Италии, в том числе Ареццо, Флоренции, Сиене и Риме. Рассказ об обучении у Пьеро делла Франчески известен по Вазари.','К 1490-м годам он руководил успешной мастерской. Среди его крупных работ — фрески «Страшного суда» в соборе Орвието. В карточке подробно рассмотрен более ранний алтарь «Обрезание Христа», около 1490–1491 годов.'],
['Фигуры помещены под полукуполом в пространстве, задуманном как продолжение реальной капеллы. Яркие плиты пола привлекают внимание, а их белые границы ведут глаз к Младенцу. Живописные мраморы и круглые рельефы усиливают архитектурную иллюзию.','Картина написана маслом по дереву и позднее перенесена на холст. Техническое исследование выявило три изменения позы Христа; его нынешний вид принадлежит Содоме, работавшему в Вольтерре в конце 1530-х годов.'],
'Синьорелли связывает фигуры, жесты и перспективу с местом показа картины. Алтарь не просто изображает библейскую сцену: его архитектура продолжает капеллу, а движение взгляда от пола к главной группе делает зрителя участником созерцания.',
['Архитектурная иллюзия: пространство картины продолжает капеллу.','Перспективный пол: белые границы плит ведут к центру действия.','Выразительный жест: поднятые руки Симеона передают узнавание Мессии.','Материальное богатство: цветные мраморы и золочёная ткань усиливают торжественность.','Подпись: надпись называет мастера Лукой из Кортоны.'],
'Выбран сюжет Обрезания и наречения имени, а не просто Сретения: надписи и присутствие Симеона соединяют разные мотивы. Фигура Христа переписана Содомой; объяснение этого сыростью восходит к Вазари и не доказано. Связь чаши с Евхаристией — интерпретация музея. Карточка подготовлена без репродукции: музейный объект подтверждён, но полную страницу конкретного файла Commons получить не удалось, поэтому статус фотографии не проверен. Сведения о материале приняты по текущему музейному паспорту.',
'luca-signorelli-the-circumcision','NG1128','Обрезание Христа','The Circumcision','около 1490–1491','Масло; первоначально по дереву, перенесено на холст; 258,5 × 180 см',null,'','luca-signorelli');
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

