/* artists-batch-39.js */
(()=>{'use strict';
const C='https://commons.wikimedia.org/wiki/',B={};
function add(id,name,latin,life,aliases,bio,technique,innovation,features,caution,sources,key,title,originalTitle,date,medium,museum,acc,source,file,license,look){const imageSource=C+'File:'+file.replaceAll(' ','_');B[id]={name,latin,life,tag:'Италия · Флоренция, кватроченто',aliases:[name,latin,...aliases],bio,technique,innovation,features,caution,sources:[...sources,['Репродукция: сведения о файле',imageSource]],works:[{key,title,originalTitle,date,medium,museum,accessionNumber:acc,source,image:C+'Special:FilePath/'+encodeURIComponent(file)+'?width=800',zoom:C+'Special:FilePath/'+encodeURIComponent(file)+'?width=1600',imageSource,license,imageVisuallyReviewed:false,look}],editorialStatus:'museum_sources_commons_image_browser_check_pending'};}
add('andrea_del_castagno','Андреа дель Кастаньо','Andrea del Castagno','родился до 1419; умер в 1457',['Кастаньо','Андреа дель Кастанья','Castagno'],
['Флорентийский мастер первой половины XV века. Национальная галерея искусства в Вашингтоне указывает рождение до 1419 года и смерть в 1457 году. Карточка сосредоточена на «Давиде с головой Голиафа», около 1450–1455 годов, а не на полном обзоре его фресковых циклов.','Давид был политическим символом Флоренции, которой приходилось противостоять более могущественным соседям. Живописец поместил библейского героя на парадный щит — предмет для торжественного показа, а не обычную алтарную доску.'],
['Темпера по коже, укреплённой на дереве. Щит имеет высоту 115,5 см, ширину 76,5 см вверху и 40,6 см внизу. Под красочным слоем видны пять креплений, которыми он соединялся с ремнями для ношения.','Напряжённое выражение, развевающаяся одежда и волосы создают драматическое движение. Резкий силуэт рассчитан на ясность образа, тогда как свет и тень придают телу объём.'],
'Религиозный сюжет становится публичным гражданским знаком. Давид ещё замахивается пращой, но голова Голиафа уже лежит у его ног: действие и итог объединены ради ясного образа победы слабого над сильным.',
['Энергичная поза: замах превращает тело в выразительную дугу.','Развевающиеся ткани: одежда поддерживает ощущение движения.','Объёмная фигура: свет и тень подчёркивают телесность.','Два момента вместе: замах пращи и уже состоявшаяся победа.','Форма щита: композиция подчинена сужающемуся предмету.'],
'Не называй вещь боевым щитом: музей рассматривает её как церемониальный предмет. Это редкий, но не объявленный здесь единственным пример живописного парадного щита. Даты приняты по текущему каталогу NGA; во вторичных источниках они отличаются. Сюжет включает отсечённую голову. Визуальный просмотр файла и загрузка в браузере не проверены.',
[['NGA: Давид с головой Голиафа','https://www.nga.gov/artworks/1145-david-head-goliath'],['NGA и Italian Renaissance Learning Resources: парадный щит','https://www.italianrenaissanceresources.com/units/unit-5/essays/the-beautiful-chamber/']],
'nga:1145','Давид с головой Голиафа','David with the Head of Goliath','около 1450–1455','Темпера по коже на дереве; высота 115,5 см, ширина вверху 76,5 см, внизу 40,6 см','Национальная галерея искусства, Вашингтон','1942.9.8','https://www.nga.gov/artworks/1145-david-head-goliath','Andrea del Castagno, David with the Head of Goliath, c. 1450-1455, NGA 1145.jpg','CC0 1.0 Universal по странице файла Commons; источник изображения — NGA','Сравни замах Давида с уже лежащей у ног головой Голиафа: художник соединяет действие и результат. Затем проследи, как силуэт фигуры вписан в сужающийся щит.');
add('domenico_veneziano','Доменико Венециано','Domenico Veneziano','ок. 1410–1461',['Венециано','Доменико ди Бартоломео','Veneziano'],
['Доменико работал в Перудже и Флоренции в конце 1430-х годов. По обзору Лондонской Национальной галереи, он был связан с Джентиле да Фабриано и Пизанелло; многие его фрески утрачены, а главным сохранившимся ансамблем стал алтарь святой Лючии во Флоренции.','Его обращение со светом и цветом повлияло на Пьеро делла Франческа, которого он обучал. Небольшой «Иоанн Креститель в пустыне» из Вашингтона происходит из основания алтаря церкви Санта-Лючия-деи-Маньоли.'],
['Темпера по доске, 28,4 × 31,8 см. Молодой Иоанн меняет богатую мирскую одежду на грубую власяницу из верблюжьего волоса. Художник делает центром сцены решение отказаться от роскоши ради благочестия.','Почти античная по типу обнажённая фигура помещена в условные скалистые горы. Пейзаж не столько описывает реальное место, сколько подчёркивает суровость добровольно избранной жизни.'],
'Античный идеал человеческого тела соединяется с христианским подвигом отречения. Золотой нимб превращает классический образ юноши в святого, а готическая условность гор сосуществует с новым интересом к телесности.',
['Юный святой: вместо привычного бородатого отшельника показан молодой человек.','Античная телесность: фигура напоминает классический идеал.','Смена одежды: действие выражает нравственный выбор.','Символические горы: суровая среда усиливает смысл отказа от удобств.','Небольшой формат: эпизод предназначался для нижней части алтаря.'],
'Это панель пределлы, не центральная часть алтаря. Дата около 1445–1450 принята по NGA; на странице файла стоит около 1445. Не принимай условные скалы за недостаток наблюдения: музей объясняет их выразительную функцию. Название «Венециано» не означает, что выбранная работа принадлежит венецианской школе XVI века. Визуальный просмотр и загрузка в браузере не проверены.',
[['NGA: Иоанн Креститель в пустыне','https://www.nga.gov/artworks/12146-saint-john-desert'],['Национальная галерея, Лондон: Доменико Венециано','https://www.nationalgallery.org.uk/artists/domenico-veneziano'],['Зеркало страницы Commons: сведения о репродукции','https://en.wikipedia.org/wiki/File:Domenico_Veneziano_001.jpg']],
'nga:12146','Иоанн Креститель в пустыне','Saint John in the Desert','около 1445–1450','Темпера по доске; 28,4 × 31,8 см','Национальная галерея искусства, Вашингтон','1943.4.48','https://www.nga.gov/artworks/12146-saint-john-desert','Domenico Veneziano 001.jpg','PD-Art по странице файла: репродукция двумерного произведения в общественном достоянии; условия использования могут различаться по странам','Найди богатую одежду, от которой отказывается Иоанн, и грубую власяницу. Сравни спокойную классическую фигуру с острыми скалами: они делают духовный выбор героя особенно ощутимым.');
add('benozzo_gozzoli','Беноццо Гоццоли','Benozzo Gozzoli','ок. 1420/1422–1497',['Гоццоли','Беноццо Гоззоли','Gozzoli'],
['Гоццоли происходил из флорентийской семьи. Он работал у скульптора Лоренцо Гиберти, а затем стал главным помощником Фра Анджелико в Риме и Орвието. В 1468–1494 или 1495 годах он почти постоянно находился в Пизе; умер в Пистое.','Метрополитен-музей связывает его привлекательную повествовательную манеру с опытом работы у Анджелико и Гиберти. «Святой Пётр и Симон Волхв» — одна из четырёх панелей, заказанных флорентийской семьёй Алессандри в 1460-х годах для обновления гораздо более старого алтаря.'],
['Темпера по дереву, 40 × 45,7 см. По легендарному рассказу, Симон летит благодаря демонам; по велению Петра они отпускают его, и он падает перед императором Нероном. Небольшая панель разворачивает событие в многофигурное зрелище.','Мастер распределяет действие между главными персонажами и свидетелями. Повторение героя в воздухе и на земле показывает разные моменты истории внутри одного изображения.'],
'Гоццоли превращает небольшой религиозный эпизод в увлекательный рассказ. Заказ показывает и другой аспект Возрождения: новые панели могли не заменять старый алтарь целиком, а обновлять ансамбль, созданный примерно за полтора столетия до них.',
['Насыщенный рассказ: много фигур участвует в одном эпизоде.','Последовательность внутри картины: полёт и падение показаны вместе.','Выразительные жесты: персонажи направляют внимание зрителя.','Святые и светская власть: Пётр действует перед Нероном.','Обновление ансамбля: новая живопись дополняла старый алтарь.'],
'Сюжет относится к легендарному преданию, а не к документальной истории. Работа Метрополитен-музея имеет номер 15.106.1: не путай её с другой композицией падения Симона из Королевского собрания. Метрополитен-музей называет заказ 1460-х годов; точный год здесь не придуман. Изображение идентифицировано по названию и музейному номеру в категории Commons; статус Public Domain подтверждён музейной страницей. Загрузку файла в браузере и визуальный просмотр не проверял.',
[['Метрополитен-музей: Святой Пётр и Симон Волхв','https://www.metmuseum.org/art/collection/search/436563'],['Национальная галерея, Лондон: Беноццо Гоццоли','https://www.nationalgallery.org.uk/artists/benozzo-gozzoli'],['Commons: категория работ Гоццоли в Метрополитен-музее','https://commons.wikimedia.org/wiki/Category:Paintings_by_Benozzo_Gozzoli_in_the_Metropolitan_Museum_of_Art']],
'met:436563','Святой Пётр и Симон Волхв','Saint Peter and Simon Magus','1460-е годы, по описанию заказа','Темпера по дереву; 40 × 45,7 см','Метрополитен-музей, Нью-Йорк','15.106.1','https://www.metmuseum.org/art/collection/search/436563','Gozzoli - Saint Peter and Simon Magus, 15.106.1, DP-19452-001.jpg','Public Domain / Met Open Access: статус произведения и доступность музейных изображений подтверждены страницей Метрополитен-музея','Найди Симона в воздухе и его же после падения. Затем отыщи Петра и Нерона: жесты участников помогают проследить связь между разными моментами легенды.');
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

