/* artists-batch-41.js */
(()=>{'use strict';
const N='https://www.nationalgallery.org.uk/',C='https://commons.wikimedia.org/wiki/',B={};
function add(id,name,latin,life,aliases,bio,technique,innovation,features,caution,sources,key,title,originalTitle,date,medium,museum,acc,source,file,license,look){const imageSource=C+'File:'+encodeURIComponent(file.replaceAll(' ','_'));B[id]={name,latin,life,tag:'Италия · Венеция, кватроченто',aliases:[name,latin,...aliases],bio,technique,innovation,features,caution,sources:[...sources,['Commons: репродукция и права',imageSource]],works:[{key,title,originalTitle,date,medium,museum,accessionNumber:acc,source,image:C+'Special:FilePath/'+encodeURIComponent(file)+'?width=800',zoom:C+'Special:FilePath/'+encodeURIComponent(file)+'?width=1600',imageSource,license,imageVisuallyReviewed:false,look}],editorialStatus:'museum_sources_commons_image_browser_check_pending'};}
add('giovanni_bellini','Джованни Беллини','Giovanni Bellini','ок. 1435–1516',['Джамбеллино','Giambellino'],
['Джованни происходил из ведущей семьи венецианских живописцев. Его становление связано с отцом Якопо, старшим братом Джентиле и шурином Андреа Мантеньей. Он прожил долгую творческую жизнь в Венеции и был одним из самых влиятельных мастеров города.','Национальная галерея особенно выделяет его передачу естественного света, нежные образы Богоматери и алтари. Раннее «Моление о чаше» около 1458–1460 годов позволяет сравнить его искусство с одноимённой картиной Мантеньи из батча 36.'],
['Яичная темпера по дереву, вероятно тополю. Краска высыхает быстро и не смешивается так легко, как масло, но Беллини точно передаёт тёплое рассветное освещение: розовая одежда Христа перекликается с персиковым небом и подсвеченными облаками.','Часть скал и резкие складки напоминают Мантенью, однако округлые формы, извилистые дороги и мягкие переходы ландшафта создают другую пространственную среду. Дальний отряд Иуды движется к переднему плану, связывая молитву с будущим арестом.'],
'Пейзаж становится носителем настроения и религиозного смысла. Свет объединяет отдельные предметы в общую среду; он не просто делает фигуры видимыми, а помогает выразить духовное присутствие и напряжение евангельской сцены.',
['Рассветный свет: тёплое освещение связывает небо, одежду и землю.','Мягкий ландшафт: округлые формы и извилистые линии отличаются от каменной строгости Мантеньи.','Дальний рассказ: Иуда и солдаты ещё только приближаются.','Символическая архитектура природы: скала под Христом напоминает алтарь.','Точный цвет темперы: ранняя работа достигает световых эффектов без масла.'],
'Не путай Джованни с Джентиле Беллини; общий алиас «Беллини» намеренно не добавлен. NG726 — не «Моление о чаше» Мантеньи NG1417. Выбранная картина написана темперой, хотя позднее художник работал и маслом. Музей датирует её около 1458–1460 и даёт высоту 80,4 см; на Commons есть иные округления и старые даты. Карьера продолжалась в XVI веке. Визуальный просмотр и загрузка в браузере не проверены.',
[['Национальная галерея: Джованни Беллини',N+'artists/giovanni-bellini'],['Национальная галерея: Моление о чаше, NG726',N+'paintings/giovanni-bellini-the-agony-in-the-garden']],
'ng:NG726','Моление о чаше','The Agony in the Garden','около 1458–1460','Яичная темпера по дереву, вероятно тополю; 80,4 × 127 см','Национальная галерея, Лондон','NG726',N+'paintings/giovanni-bellini-the-agony-in-the-garden','Bellini,Giovanni - Agony in the Garden - National Gallery.jpg','PD-Art по странице Commons; повторное использование фотографических репродукций может регулироваться по-разному в разных странах','Сравни персиковое небо с розовой одеждой Христа. Затем проследи извилистую дорогу от Иуды и солдат к переднему плану. Сопоставь мягкие формы и свет с более каменным пространством Мантеньи.');
add('gentile_bellini','Джентиле Беллини','Gentile Bellini','работал около 1460; умер в 1507',['Джентиле'],
['Джентиле был сыном Якопо и старшим братом Джованни Беллини, руководил семейной мастерской. Многие его большие работы для Дворца дожей погибли при пожаре 1577 года, поэтому сохранившиеся произведения не дают полного представления о его деятельности.','В 1479 году венецианское правительство направило его в Константинополь к султану Мехмеду II, запросившему живописца. Он оставался там до 1481 года: поездка была одновременно художественной и дипломатической миссией, связанной с торговыми и политическими отношениями.'],
['Масло, первоначально по дереву, позднее перенесённое на холст. Султан повёрнут в три четверти, а не в традиционный для многих венецианских правительственных портретов профиль. Каменная арка и выступающий парапет отделяют фигуру от зрителя.','Узоры резной арки, ткань с драгоценными камнями и жемчугом, мех и тюрбан демонстрируют статус модели. Три короны по обе стороны арки, возможно, обозначают подвластные султану территории.'],
'Портрет показывает, как ренессансный язык репрезентации пересекает политические и культурные границы. Античные мотивы арки, новый поворот головы и османские знаки власти соединены в образ правителя, созданный в рамках дипломатического обмена.',
['Трёхчетвертной поворот: лицо и корпус слегка обращены к зрителю.','Арка-обрамление: классические мотивы создают торжественную рамку.','Парапет: ткань и украшения вынесены к переднему краю.','Знаки власти: короны и дорогой костюм возвеличивают модель.','Межкультурный заказ: венецианский живописец работает для османского султана.'],
'Портрет сильно повреждён и почти целиком переписан, особенно фигура; V&A отмечает вмешательства XIX века. Нынешнюю поверхность нельзя целиком считать собственноручной живописью Джентиле 1480 года. Дата 25 ноября 1480 сохранилась в старой надписи, а надпись слева реконструирована позднее. Толкование корон как Греции, Трапезунда и Азии — вероятное объяснение, не бесспорный ключ. 1460 — год активности, не рождения. Визуальный просмотр и загрузка в браузере не проверены.',
[['Национальная галерея: Джентиле Беллини',N+'artists/gentile-bellini'],['Национальная галерея: Султан Мехмед II, NG3099',N+'paintings/gentile-bellini-the-sultan-mehmet-ii'],['V&A: состояние и поздняя перепись портрета','https://collections.vam.ac.uk/item/O1244642/the-sultan-mehmet-ii-oil-painting-bellini-gentile/']],
'ng:NG3099','Султан Мехмед II','The Sultan Mehmet II','1480; значительные позднейшие записи','Масло; первоначально по дереву, перенесено на холст; 69,9 × 52,1 см','Национальная галерея, Лондон','NG3099',N+'paintings/gentile-bellini-the-sultan-mehmet-ii','Bellini, Gentile - Sultan Mehmet II.jpg','Public Domain по Commons / Yorck Project; сведения о составе цифрового собрания приведены на странице файла','Проследи арку вокруг фигуры и найди по три короны с каждой стороны. Сравни дорогую ткань на парапете с сдержанным поворотом лица. Помни о сильной поздней переписи: это не нетронутый живописный слой XV века.');
add('vittore_carpaccio','Витторе Карпаччо','Vittore Carpaccio','ок. 1465–1525/1526',['Карпаччо','Carpaccio','Витторе Скарпацца'],
['Карпаччо — венецианский мастер повествовательной живописи. Его работам свойственны внимание к современному городу, костюмам и занятиям людей. Даты рождения в музейных справочниках различаются; здесь использована датировка Getty: около 1465 года.','«Охота в лагуне» около 1490–1495 годов была верхней частью одной доски с «Двумя венецианками», теперь находящимися в музее Коррер. На обороте сохранилась обманка с письмами; следы петель и защёлки указывают, что доска могла служить ставней или дверцей шкафа.'],
['Масло по дереву. Плоскодонные лодки с гребцами и стрелками распределены по воде так, что пространство кажется продолжением реального вида из окна. Далекие берега и постройки расширяют повседневный сюжет до панорамы лагуны.','У нижнего левого края виден непропорционально большой цветок лилии. Он соединяется со стеблем в вазе на нижней части доски из музея Коррер; совпадение древесного рисунка подтвердило первоначальное единство двух фрагментов.'],
'Живопись превращает предмет обстановки в зрительную иллюзию: открытая створка обещает вид на лагуну, а оборот обманывает глаз изображением писем. Современное разделение фрагментов меняет смысл и масштаб деталей, поэтому реконструкция вещи важна не меньше анализа стиля.',
['Панорама повседневности: показаны лодки, гребцы и охотники.','Иллюзорное окно: вид связан с функцией створки.','Предмет-загадка: слишком крупная лилия объясняется утраченной связью с нижней панелью.','Двусторонняя вещь: сюжет и обманка существуют на разных сторонах.','Материальное доказательство: древесный рисунок связывает музейные фрагменты.'],
'Getty описывает охоту на бакланов глиняными шариками, а не стрелами: это не установленная сцена рыбной ловли с прирученными птицами. Створка окна или дверца шкафа — вероятные функции, не окончательный вывод. В works показана только лицевая сторона «Охота в лагуне», не оборот и не совмещение с панелью Коррер. Точный момент распила неизвестен; вероятно, он произошёл до XIX века. Оригинал файла Commons около 90 МБ: ссылки ведут только на уменьшенные версии. Визуальный просмотр и загрузка в браузере не проверены.',
[['Getty: Охота в лагуне; оборот с письмами','https://www.getty.edu/art/collection/object/103REK'],['Getty CONA: размеры и материал','https://www.getty.edu/cona/CONAFullSubject.aspx?subid=700002120'],['Getty: Open Content Program','https://www.getty.edu/about/whatwedo/opencontent.html']],
'getty:79.PB.72:recto','Охота в лагуне','Hunting on the Lagoon (recto)','около 1490–1495','Масло по дереву; 75,6 × 63,8 см','Музей Дж. Пола Гетти, Лос-Анджелес','79.PB.72','https://www.getty.edu/art/collection/object/103REK','Vittore Carpaccio - Hunting on the Lagoon (recto), Letter Rack (verso) - 79.PB.72 - J. Paul Getty Museum.jpg','Public Domain / PD-Art по Commons; Digital image courtesy of Getty’s Open Content Program','Найди большой цветок лилии внизу слева: он кажется чужим пейзажу, потому что вырос из вазы на другой части первоначальной доски. Затем отыщи летящий глиняный шарик и сравни лодки, расположенные на разных планах.');
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

